INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'anas-platyrhynchos', 'ka', 'სად გვხვდება გარეული იხვი საქართველოში', 'გარეული იხვის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. წყაროებით დადასტურებული რეგიონები და ინდივიდუალური საველე ჩანაწერები ცალკე ფენებია; ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვედ არ უნდა განვიხილოთ.', 'გარეული იხვის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'anas-platyrhynchos');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'anas-platyrhynchos', 'en', 'Mallard: where it occurs in Georgia', 'The mallard map combines Reptiles.ge editorial photo records with public iNaturalist observations. Source-confirmed regions and individual field records are separate layers, and record counts reflect observation effort rather than population density.', 'Mallard distribution evidence and field records on a map of Georgia', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'anas-platyrhynchos');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'anas-platyrhynchos', 'ru', 'Где встречается кряква в Грузии', 'Карта кряквы объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы, подтверждённые источниками, и отдельные полевые записи показаны разными слоями; количество записей отражает интенсивность наблюдений, а не плотность популяции.', 'Данные о распространении кряквы и полевые записи на карте Грузии', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'anas-platyrhynchos');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'anas-platyrhynchos', 'tr', 'Yeşilbaş Gürcistan''da nerede görülür?', 'Yeşilbaş haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Kaynakla doğrulanmış bölgeler ile tekil arazi kayıtları ayrı katmanlardır; kayıt sayısı gözlem yoğunluğunu yansıtır, popülasyon yoğunluğu değildir.', 'Yeşilbaşın Gürcistan''daki yayılış kanıtları ve arazi kayıtları', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'anas-platyrhynchos');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'anguis-colchica', 145895, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'anguis-colchica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'anguis-colchica', 'ka', 'სად არის ბოხმეჭა დაფიქსირებული საქართველოში', 'ბოხმეჭას რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. გამოკვეთილი რეგიონები ჩანაწერების რეგიონული ცხრილიდანაა: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი, სხვა შემთხვევაში რეგიონი გავრცელებულად არ ჩაითვლება. დაფარული ან მიახლოებითი საჯარო კოორდინატი ჩანაწერს რეგიონს არ მიაკუთვნებს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს. Tarkhnishvili et al. 2026 ამ ტაქსონს კანდიდატად ტოვებს; რუკის სტატუსი სახეობრივ რანგს არ ადასტურებს.', 'ბოხმეჭას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'anguis-colchica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'anguis-colchica', 'en', 'Colchis slow worm: where it is recorded in Georgia', 'The Colchis slow worm map uses public iNaturalist observations in Georgia. Shaded regions come from the records-by-region table: only regions with enough records are shaded on the map, and any other region is not. Obscured or approximate public coordinates do not place a record in a region. Record counts reflect observation effort, not population density. Tarkhnishvili et al. 2026 still treat this taxon as a candidate; the map status does not settle species rank.', 'Colchis slow worm observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'anguis-colchica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'anguis-colchica', 'ru', 'Где колхидская веретеница отмечена в Грузии', 'Карта колхидской веретеницы основана на публичных наблюдениях iNaturalist в Грузии. Залитые регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей, в остальных случаях регион распространением не считается. Скрытые или приблизительные публичные координаты не относят запись к региону. Число записей отражает активность наблюдателей, а не плотность популяции. Tarkhnishvili et al. 2026 по-прежнему считают этот таксон кандидатом; статус на карте не утверждает видовой ранг.', 'Наблюдения колхидской веретеницы и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'anguis-colchica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'anguis-colchica', 'tr', 'Kolhis yılan kertenkele Gürcistan’da nerede kaydedildi?', 'Kolhis yılan kertenkele haritası Gürcistan’daki herkese açık iNaturalist gözlemlerini kullanır. Taralı bölgeler, bölgelere göre kayıt tablosundan gelir: haritada yalnızca yeterli kaydı olan bölgeler taranır, diğer durumlarda bölge yayılış sayılmaz. Gizlenmiş veya yaklaşık kamuya açık koordinatlar bir kaydı bölgeye atamaz. Kayıt sayıları gözlem çabasını gösterir, nüfus yoğunluğunu değil. Tarkhnishvili et al. 2026 bu taksonu hâlâ aday sayar; harita durumu tür rütbesini karara bağlamaz.', 'Kolhis yılan kertenkelenin gözlemleri ve kayıt bulunan bölgeler, Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'anguis-colchica');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'aquila-chrysaetos', 5074, 'record-summary', 4 WHERE EXISTS (SELECT 1 FROM species WHERE id = 'aquila-chrysaetos');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'aquila-chrysaetos', 'ka', 'სად არის მთის არწივი დაფიქსირებული საქართველოში', 'მთის არწივის რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოდან. ცხრილში რეგიონი რუკაზე გამოიყოფა მინიმუმ ოთხი ჩანაწერით; ნაკლები ჩანაწერის მქონე რეგიონი მონიშნულია როგორც „ჩანაწერები ცოტაა“. ჩანაწერების რაოდენობა ასახავს დაკვირვების ინტენსივობას და არა პოპულაციის სიმჭიდროვეს ან ბუდობის სტატუსს.', 'მთის არწივის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'aquila-chrysaetos');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'aquila-chrysaetos', 'en', 'Golden eagle: where it is recorded in Georgia', 'The golden eagle map uses public iNaturalist observations from Georgia. A region is shaded on the map with at least four records in the table; regions with fewer records are marked “Too few records”. Record counts reflect observation effort, not population density or breeding status.', 'Golden eagle observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'aquila-chrysaetos');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'aquila-chrysaetos', 'ru', 'Где беркут отмечен в Грузии', 'Карта беркута использует публичные наблюдения iNaturalist из Грузии. Регион выделяется на карте при наличии в таблице минимум четырёх записей; регионы с меньшим числом записей отмечены как «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции или статус гнездования.', 'Наблюдения беркута и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'aquila-chrysaetos');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'aquila-chrysaetos', 'tr', 'Kaya kartalı Gürcistan''da nerede kaydedildi?', 'Kaya kartalı haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Tabloda en az dört kayıt bulunan bölgeler haritada gölgelendirilir; daha az kayıt bulunan bölgeler “Kayıt az” olarak işaretlenir. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu veya üreme durumunu değil.', 'Kaya kartalı gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'aquila-chrysaetos');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'araneus-diadematus', 52628, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'araneus-diadematus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'araneus-diadematus', 'ka', 'სად არის ჩვეულებრივი ჯვრიანა დაფიქსირებული საქართველოში', 'ჩვეულებრივი ჯვრიანას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი.', 'ჩვეულებრივი ჯვრიანას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'araneus-diadematus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'araneus-diadematus', 'en', 'European garden spider: where it is recorded in Georgia', 'The European garden spider map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'European garden spider distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'araneus-diadematus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'araneus-diadematus', 'ru', 'Где обыкновенный крестовик отмечен в Грузии', 'Карта обыкновенного крестовика объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте выделены только регионы с достаточным числом записей.', 'Данные о распространении обыкновенного крестовика и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'araneus-diadematus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'araneus-diadematus', 'tr', 'Avrupa bahçe örümceği Gürcistan''da nerede kaydedildi?', 'Avrupa bahçe örümceği haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir.', 'Avrupa bahçe örümceğinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'araneus-diadematus');
