INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'bufo-verrucosissimus', 'ka', 'სად არის კავკასიური გომბეშო დაფიქსირებული საქართველოში', 'კავკასიური გომბეშოს რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'კავკასიური გომბეშოს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'bufo-verrucosissimus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'bufo-verrucosissimus', 'en', 'Where the Caucasian toad is recorded in Georgia', 'The Caucasian toad map combines Reptiles.ge editorial photo records with public iNaturalist photo observations in Georgia. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records. Record counts reflect observation effort, not population density.', 'Caucasian toad field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'bufo-verrucosissimus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'bufo-verrucosissimus', 'ru', 'Где кавказская жаба отмечена в Грузии', 'Карта кавказской жабы объединяет редакционные фотозаписи Reptiles.ge и публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало. Число записей отражает интенсивность наблюдений, а не плотность популяции.', 'Полевые записи кавказской жабы и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'bufo-verrucosissimus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'bufo-verrucosissimus', 'tr', 'Kafkasya karakurbağası Gürcistan''da nerede kaydedildi?', 'Kafkasya karakurbağası haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır. Kayıt sayısı popülasyon yoğunluğunu değil, gözlem yoğunluğunu yansıtır.', 'Kafkasya karakurbağasının Gürcistan haritasında arazi kayıtları ve kayıt bulunan bölgeler', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'bufo-verrucosissimus');
