INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'bufotes-viridis', 'ka', 'სად არის მწვანე გომბეშო დაფიქსირებული საქართველოში', 'მწვანე გომბეშოს რუკა ეყრდნობა iNaturalist-ის საჯარო ფოტოდაკვირვებებს საქართველოდან. რუკაზე მონიშნულია მხოლოდ ის რეგიონები, რომლებსაც ჩანაწერების რეგიონულ ცხრილში საკმარისი ჩანაწერი აქვს; დანარჩენი წერტილები ცალკეული ჩანაწერებია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მწვანე გომბეშოს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'bufotes-viridis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'bufotes-viridis', 'en', 'Where the green toad is recorded in Georgia', 'The green toad map uses public iNaturalist photo observations from Georgia. Only regions with enough records in the records-by-region table are shaded on the map; other points are individual records. Record counts reflect observation effort, not population density.', 'Green toad field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'bufotes-viridis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'bufotes-viridis', 'ru', 'Где зелёная жаба отмечена в Грузии', 'Карта зелёной жабы основана на публичных фотонаблюдениях iNaturalist из Грузии. На карте закрашены только регионы с достаточным числом записей в таблице записей по регионам; остальные точки — отдельные записи. Число записей отражает интенсивность наблюдений, а не плотность популяции.', 'Полевые записи зелёной жабы и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'bufotes-viridis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'bufotes-viridis', 'tr', 'Yeşil karakurbağa Gürcistan''da nerede kaydedildi?', 'Yeşil karakurbağa haritası Gürcistan''dan herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. Haritada yalnızca bölgelere göre kayıt tablosunda yeterli kaydı olan bölgeler gösterilir; diğer noktalar tekil kayıtlardır. Kayıt sayısı popülasyon yoğunluğunu değil, gözlem yoğunluğunu yansıtır.', 'Yeşil karakurbağanın Gürcistan haritasında arazi kayıtları ve kayıt bulunan bölgeler', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'bufotes-viridis');
