INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ciconia-ciconia', 'ka', 'სად არის თეთრი ყარყატი დაფიქსირებული საქართველოში', 'თეთრი ყარყატის რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი, დანარჩენში ჩანაწერები ცოტაა. ეს ჩანაწერები თავისთავად ბუდობას არ ადასტურებს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'თეთრი ყარყატის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ciconia-ciconia');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ciconia-ciconia', 'en', 'White stork: where it is recorded in Georgia', 'The white stork map uses public iNaturalist observations from Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions have too few records. These observations do not by themselves establish breeding. Record counts reflect observation effort, not population density.', 'White stork observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ciconia-ciconia');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ciconia-ciconia', 'ru', 'Где белый аист отмечен в Грузии', 'Карта белого аиста основана на публичных наблюдениях iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей, в остальных записей мало. Эти наблюдения сами по себе не доказывают гнездование. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения белого аиста и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ciconia-ciconia');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ciconia-ciconia', 'tr', 'Leylek Gürcistan''da nerede kaydedildi?', 'Leylek haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan gelir: haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir; diğerlerinde kayıt azdır. Bu gözlemler tek başına üremeyi kanıtlamaz. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Leylek gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ciconia-ciconia');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'columba-livia', 3017, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'columba-livia');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'columba-livia', 'ka', 'სად არის გარეული მტრედი დაფიქსირებული საქართველოში', 'გარეული მტრედის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი; სხვა შემთხვევაში რეგიონი გავრცელებულად არ ითვლება. ეს ჩანაწერები გენეტიკურად ველურ ფრინველსა და ქალაქში თავისუფლად მცხოვრებ მტრედს ერთმანეთისგან არ ჰყოფს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'გარეული მტრედის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'საკმარისი ჩანაწერების მქონე რეგიონი', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'columba-livia');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'columba-livia', 'en', 'Rock Dove: where it is recorded in Georgia', 'The Rock Dove map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; otherwise a region is not treated as part of the range. These records do not separate genetically wild birds from free-living city pigeons. Record counts reflect observation effort, not population density.', 'Rock Dove observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'columba-livia');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'columba-livia', 'ru', 'Где сизый голубь отмечен в Грузии', 'Карта сизого голубя использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; в остальных случаях регион распространением не считается. Эти записи не отделяют генетически диких птиц от свободно живущих городских голубей. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения сизого голубя и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'columba-livia');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'columba-livia', 'tr', 'Kaya güvercini Gürcistan''da nerede kaydedildi?', 'Kaya güvercini haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir; aksi halde bölge yayılış sayılmaz. Bu kayıtlar genetik olarak yabani kuşları şehirde serbest yaşayan güvercinlerden ayırmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kaya güvercini gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'columba-livia');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'columba-palumbus', 3048, 'record-summary', 1 WHERE EXISTS (SELECT 1 FROM species WHERE id = 'columba-palumbus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'columba-palumbus', 'ka', 'სად არის ქედანი დაფიქსირებული საქართველოში', 'რუკა საქართველოში iNaturalist-ის საჯარო, ფოტოდადასტურებულ დაკვირვებებს ეყრდნობა. რეგიონი რუკაზე გამოიკვეთება, თუ მასში სულ მცირე ერთი შენარჩუნებული ჩანაწერია. წერტილები და გამოკვეთილი რეგიონები არსებობის მტკიცებულებაა და არა მთელ რეგიონში უწყვეტი გავრცელება. ზოგი საჯარო კოორდინატი მიახლოებითია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ქედანის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'columba-palumbus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'columba-palumbus', 'en', 'Common woodpigeon: where it is recorded in Georgia', 'This map uses public, photo-backed iNaturalist observations in Georgia. A region with at least one retained record is shaded on the map. Points and shading show evidence of occurrence, not continuous presence across a region. Some public coordinates are approximate. Record counts reflect observation effort, not population density.', 'Common woodpigeon observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'columba-palumbus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'columba-palumbus', 'ru', 'Где вяхирь отмечен в Грузии', 'Карта использует публичные наблюдения iNaturalist с фотографиями из Грузии. Регион выделяется на карте при наличии не менее одной сохранённой записи. Точки и выделение показывают свидетельства присутствия, а не сплошное распространение по региону. Некоторые публичные координаты приблизительны. Число записей отражает усилия наблюдателей, а не плотность популяции.', 'Наблюдения вяхиря и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'columba-palumbus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'columba-palumbus', 'tr', 'Tahtalı Gürcistan''da nerede kaydedildi?', 'Harita, Gürcistan''daki fotoğraflı halka açık iNaturalist gözlemlerini kullanır. En az bir tutulan kaydı olan bölge haritada vurgulanır. Noktalar ve vurgular, bölgenin tamamında kesintisiz yayılışı değil, varlık kanıtını gösterir. Bazı açık koordinatlar yaklaşıktır. Kayıt sayısı popülasyon yoğunluğunu değil gözlem çabasını yansıtır.', 'Tahtalı gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'columba-palumbus');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'coronella-austriaca', 26904, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'coronella-austriaca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'coronella-austriaca', 'ka', 'სად არის სპილენძა დაფიქსირებული საქართველოში', 'სპილენძას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი.', 'სპილენძას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'coronella-austriaca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'coronella-austriaca', 'en', 'Smooth snake: where it is recorded in Georgia', 'The smooth snake map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'Smooth snake distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'coronella-austriaca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'coronella-austriaca', 'ru', 'Где медянка отмечена в Грузии', 'Карта медянки объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте выделены только регионы с достаточным числом записей.', 'Данные о распространении медянки и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'coronella-austriaca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'coronella-austriaca', 'tr', 'Avusturya yılanı Gürcistan''da nerede kaydedildi?', 'Avusturya yılanı haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir.', 'Avusturya yılanının Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'coronella-austriaca');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'coturnix-coturnix', 804, 'record-summary', 1 WHERE EXISTS (SELECT 1 FROM species WHERE id = 'coturnix-coturnix');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'coturnix-coturnix', 'ka', 'სად არის მწყერი დაფიქსირებული საქართველოში', 'მწყრის რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოდან. რეგიონები აღებულია ქვემოთ მოცემული ჩანაწერების ცხრილიდან; ამ სახეობისთვის ერთი ჩანაწერიც საკმარისია, რომ რეგიონი რუკაზე გამოიყოს. რეგიონული პოლიგონების გარეთ დარჩენილი წერტილები საერთო რაოდენობაში შედის, მაგრამ რეგიონს არ მიეკუთვნება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობასაც ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'მწყრის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'coturnix-coturnix');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'coturnix-coturnix', 'en', 'Common Quail: where it is recorded in Georgia', 'The Common Quail map uses public iNaturalist observations from Georgia. Regions come from the records-by-region table; for this species, a region with at least one record is shaded on the map. Points outside the regional polygons remain in the total without being assigned to a region. Record counts reflect observation effort, not population density.', 'Common Quail observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'coturnix-coturnix');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'coturnix-coturnix', 'ru', 'Где перепел отмечен в Грузии', 'Карта перепела использует публичные наблюдения iNaturalist из Грузии. Регионы взяты из таблицы записей; для этого вида одной записи достаточно, чтобы регион был выделен на карте. Точки вне региональных полигонов включены в общее число, но не отнесены к региону. Число записей отражает также активность наблюдателей, а не плотность популяции.', 'Наблюдения перепела и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'coturnix-coturnix');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'coturnix-coturnix', 'tr', 'Bıldırcın Gürcistan''da nerede kaydedildi?', 'Bıldırcın haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Bölgeler kayıt tablosundan alınır; bu tür için tek bir kayıt, bölgenin haritada gölgelendirilmesi için yeterlidir. Bölge poligonlarının dışındaki noktalar genel toplama dahildir, ancak bir bölgeye atanmaz. Kayıt sayısı gözlem çabasını da yansıtır, nüfus yoğunluğunu ölçmez.', 'Bıldırcın gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'coturnix-coturnix');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'cuculus-canorus', 1907, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'cuculus-canorus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'cuculus-canorus', 'ka', 'სად არის გუგული დაფიქსირებული საქართველოში', 'გუგულის რუკა ეყრდნობა iNaturalist-ის საჯარო ფოტოდაკვირვებებს საქართველოდან. რუკაზე მონიშნულია მხოლოდ ის რეგიონები, რომლებსაც ჩანაწერების რეგიონულ ცხრილში საკმარისი ჩანაწერი აქვს; დანარჩენი წერტილები ცალკეული ჩანაწერებია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'გუგულის საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'cuculus-canorus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'cuculus-canorus', 'en', 'Where the common cuckoo is recorded in Georgia', 'The cuckoo map uses public iNaturalist photo observations from Georgia. Only regions with enough records in the records-by-region table are shaded on the map; other points are individual records. Record counts reflect observation effort, not population density.', 'Common cuckoo field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'cuculus-canorus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'cuculus-canorus', 'ru', 'Где обыкновенная кукушка отмечена в Грузии', 'Карта кукушки основана на публичных фотонаблюдениях iNaturalist из Грузии. На карте закрашены только регионы с достаточным числом записей в таблице записей по регионам; остальные точки — отдельные записи. Число записей отражает интенсивность наблюдений, а не плотность популяции.', 'Полевые записи обыкновенной кукушки и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'cuculus-canorus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'cuculus-canorus', 'tr', 'Guguk kuşu Gürcistan''da nerede kaydedildi?', 'Guguk kuşu haritası Gürcistan''dan herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. Haritada yalnızca bölgelere göre kayıt tablosunda yeterli kaydı olan bölgeler gösterilir; diğer noktalar tekil kayıtlardır. Kayıt sayısı popülasyon yoğunluğunu değil, gözlem yoğunluğunu yansıtır.', 'Guguk kuşunun Gürcistan haritasında arazi kayıtları ve kayıt bulunan bölgeler', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'cuculus-canorus');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-adjarica', 1403134, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-adjarica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-adjarica', 'ka', 'სად არის აჭარული კლდის ხვლიკი დაფიქსირებული საქართველოში', 'აჭარული კლდის ხვლიკის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'აჭარული კლდის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-adjarica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-adjarica', 'en', 'Ajarian rock lizard: where it is recorded in Georgia', 'The Ajarian rock lizard map combines Reptiles.ge editorial photo records with public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. Record counts reflect observation effort, not population density.', 'Ajarian rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-adjarica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-adjarica', 'ru', 'Где аджарская скальная ящерица отмечена в Грузии', 'Карта аджарской скальной ящерицы объединяет редакционные фотозаписи Reptiles.ge и публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения аджарской скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-adjarica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-adjarica', 'tr', 'Acar kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Acar kayalık kertenkelesi haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Acar kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-adjarica');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-armeniaca', 35390, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-armeniaca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-armeniaca', 'ka', 'სად არის სომხური კლდის ხვლიკი დაფიქსირებული საქართველოში', 'სომხური კლდის ხვლიკის რუკაზე ნაჩვენებია iNaturalist-ის საჯარო ფოტოდაკვირვებები საქართველოში. ზოგი დამკვირვებელი კოორდინატს დაახლოებით 28 კმ-ით ფარავს; ასეთი წერტილი მიახლოებითია და რეგიონის სტატუსში არ ითვლება. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. Darevskia-ს სახეობები ერთმანეთს ჰგვანან, ამიტომ ცალკეული დაკვირვება დადასტურებული ამოცნობა არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'სომხური კლდის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-armeniaca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-armeniaca', 'en', 'Armenian rock lizard: where it is recorded in Georgia', 'The Armenian rock lizard map shows public iNaturalist photo observations in Georgia. Some observers obscure their coordinates by about 28 km; those points are approximate and do not count toward a region''s status. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Darevskia species look alike, so a single observation is not a confirmed identification. Record counts reflect observation effort, not population density.', 'Armenian rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-armeniaca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-armeniaca', 'ru', 'Где армянская скальная ящерица отмечена в Грузии', 'На карте армянской скальной ящерицы показаны публичные фотонаблюдения iNaturalist в Грузии. Некоторые наблюдатели скрывают координаты примерно на 28 км; такие точки приблизительны и не учитываются в статусе региона. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Виды Darevskia похожи друг на друга, поэтому отдельное наблюдение не является подтверждённым определением. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения армянской скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-armeniaca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-armeniaca', 'tr', 'Ermeni kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Ermeni kayalık kertenkelesi haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini gösterir. Bazı gözlemciler koordinatlarını yaklaşık 28 km gizler; bu noktalar yaklaşıktır ve bölgenin durumuna sayılmaz. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Darevskia türleri birbirine benzer, bu yüzden tek bir gözlem doğrulanmış bir teşhis değildir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Ermeni kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-armeniaca');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-caucasica', 73750, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-caucasica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-caucasica', 'ka', 'სად არის კავკასიონის ხვლიკი დაფიქსირებული საქართველოში', 'კავკასიონის ხვლიკის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'კავკასიონის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-caucasica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-caucasica', 'en', 'Caucasian rock lizard: where it is recorded in Georgia', 'The Caucasian rock lizard map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Caucasian rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-caucasica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-caucasica', 'ru', 'Где кавказская скальная ящерица отмечена в Грузии', 'Карта кавказской скальной ящерицы использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения кавказской скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-caucasica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-caucasica', 'tr', 'Kafkas kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Kafkas kayalık kertenkelesi haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kafkas kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-caucasica');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-clarkorum', 35388, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-clarkorum');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-clarkorum', 'ka', 'სად არის თურქული ხვლიკი დაფიქსირებული საქართველოში', 'თურქული ხვლიკის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, Georgian Biodiversity Database-ის ლოკალიტეტებს ჭარნალის მიდამოებიდან და საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. iNaturalist ამ სახეობის ზუსტ ადგილს მალავს, ამიტომ მისი წერტილები მხოლოდ მიახლოებით არეალს აჩვენებს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'თურქული ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-clarkorum');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-clarkorum', 'en', 'Clark''s rock lizard: where it is recorded in Georgia', 'The Clark''s rock lizard map combines Reptiles.ge editorial photo records, Georgian Biodiversity Database localities from the Charnali area, and public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. iNaturalist hides the exact position of this species, so its points show only an approximate area. Record counts reflect observation effort, not population density.', 'Clark''s rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-clarkorum');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-clarkorum', 'ru', 'Где ящерица Кларка отмечена в Грузии', 'Карта ящерицы Кларка объединяет редакционные фотозаписи Reptiles.ge, локалитеты Georgian Biodiversity Database из окрестностей Чарнали и публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». iNaturalist скрывает точное место находки этого вида, поэтому его точки показывают лишь примерный участок. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения ящерицы Кларка и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-clarkorum');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-clarkorum', 'tr', 'Clark kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Clark kayalık kertenkelesi haritası Reptiles.ge editoryal fotoğraf kayıtlarını, Charnali çevresinden Georgian Biodiversity Database lokalitelerini ve Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. iNaturalist bu türün tam konumunu gizler, bu yüzden oradaki noktalar yalnızca yaklaşık bir alanı gösterir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Clark kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-clarkorum');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-daghestanica', 35389, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-daghestanica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-daghestanica', 'ka', 'სად არის დაღესტნური ხვლიკი დაფიქსირებული საქართველოში', 'დაღესტნური ხვლიკის რუკა აერთიანებს საქართველოს საველე ლოკალიტეტებსა და iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. iNaturalist-ის დაკვირვებები, რომელთა ამოცნობა ჯერ დადასტურებული არ არის, რუკაზე ჩანს, მაგრამ არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'დაღესტნური ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-daghestanica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-daghestanica', 'en', 'Daghestanian Rock Lizard: where it is recorded in Georgia', 'The Daghestanian Rock Lizard map combines field localities from Georgia with public iNaturalist photo observations. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. iNaturalist observations that still need an ID are shown but not counted. Record counts reflect observation effort, not population density.', 'Daghestanian Rock Lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-daghestanica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-daghestanica', 'ru', 'Где дагестанская скальная ящерица отмечена в Грузии', 'Карта дагестанской скальной ящерицы объединяет полевые локалитеты из Грузии и публичные фотонаблюдения iNaturalist. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Наблюдения iNaturalist, которым ещё нужно подтверждение определения, показаны, но не учитываются. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения дагестанской скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-daghestanica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-daghestanica', 'tr', 'Dağıstan kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Dağıstan kayalık kertenkelesi haritası Gürcistan''daki arazi lokalitelerini ve herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Tür teşhisi henüz doğrulanmamış iNaturalist gözlemleri gösterilir ama sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Dağıstan kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-daghestanica');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-dahli', 73752, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-dahli');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-dahli', 'ka', 'სად არის დალის ხვლიკი დაფიქსირებული საქართველოში', 'დალის ხვლიკის რუკა ზუსტ ლოკალიტეტებსა და iNaturalist-ის საჯარო ფოტოდაკვირვებებს აერთიანებს. ეს საჯარო კოორდინატები დაახლოებით 28 კმ-ითაა დაფარული, ამიტომ საზღვართან მდებარე წერტილი მიახლოებითია. ზუსტი ლოკალიტეტები რეგიონის ჩანაწერებში ითვლება. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'დალის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-dahli');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-dahli', 'en', 'Dahl''s rock lizard: where it is recorded in Georgia', 'The Dahl''s rock lizard map combines precise localities with public iNaturalist photo observations in Georgia. Those public coordinates are obscured by about 28 km, so a point near a regional border is approximate. Precise localities count toward a region''s records. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Dahl''s rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-dahli');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-dahli', 'ru', 'Где ящерица Даля отмечена в Грузии', 'Карта ящерицы Даля объединяет точные локалитеты и публичные фотонаблюдения iNaturalist в Грузии. Эти публичные координаты скрыты примерно на 28 км, поэтому точка у границы региона приблизительна. Точные локалитеты учитываются в записях региона. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения ящерицы Даля и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-dahli');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-dahli', 'tr', 'Dahl kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Dahl kayalık kertenkelesi haritası kesin lokaliteleri Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemleriyle birleştirir. Bu açık koordinatlar yaklaşık 28 km gizlenmiştir, bu yüzden sınıra yakın bir nokta yaklaşıktır. Kesin lokaliteler bölgenin kayıtlarına sayılır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Dahl kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-dahli');
