INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-derjugini', 'en', 'Artvin lizard: where it is recorded in Georgia', 'The Artvin lizard map uses public iNaturalist photo observations in Georgia. Those public coordinates are obscured by about 28 km, so a point near a regional border is approximate. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. Record counts reflect observation effort, not population density.', 'Artvin lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-derjugini');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-derjugini', 'ru', 'Где артвинская ящерица отмечена в Грузии', 'Карта артвинской ящерицы использует публичные фотонаблюдения iNaturalist в Грузии. Эти публичные координаты скрыты примерно на 28 км, поэтому точка у границы региона приблизительна. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения артвинской ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-derjugini');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-derjugini', 'tr', 'Artvin kertenkelesi Gürcistan''da nerede kaydedildi?', 'Artvin kertenkelesi haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bu açık koordinatlar yaklaşık 28 km gizlenmiştir, bu yüzden bölge sınırına yakın bir nokta yaklaşıktır. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Artvin kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-derjugini');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-mixta', 35386, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-mixta');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-mixta', 'ka', 'სად არის აჭარული ხვლიკი დაფიქსირებული საქართველოში', 'აჭარული ხვლიკის რუკა აერთიანებს საქართველოს საველე ლოკალიტეტებსა და iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. iNaturalist-ის დაკვირვებები, რომელთა ამოცნობა ჯერ დადასტურებული არ არის, რუკაზე ჩანს, მაგრამ არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'აჭარული ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-mixta');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-mixta', 'en', 'Mixed rock lizard: where it is recorded in Georgia', 'The mixed rock lizard map combines field localities from Georgia with public iNaturalist photo observations. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. iNaturalist observations that still need an ID are shown but not counted. Record counts reflect observation effort, not population density.', 'Mixed rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-mixta');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-mixta', 'ru', 'Где смешанная скальная ящерица отмечена в Грузии', 'Карта смешанной скальной ящерицы объединяет полевые локалитеты из Грузии и публичные фотонаблюдения iNaturalist. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Наблюдения iNaturalist, которым ещё нужно подтверждение определения, показаны, но не учитываются. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения смешанной скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-mixta');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-mixta', 'tr', 'Karışık kayalık kertenkele Gürcistan''da nerede kaydedildi?', 'Karışık kayalık kertenkele haritası Gürcistan''daki arazi lokalitelerini ve herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Tür teşhisi henüz doğrulanmamış iNaturalist gözlemleri gösterilir ama sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Karışık kayalık kertenkele gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-mixta');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-obscura', 35376, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-obscura');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-obscura', 'ka', 'სად არის მესხური კლდის ხვლიკი დაფიქსირებული საქართველოში', 'მესხური კლდის ხვლიკის რუკა აერთიანებს საქართველოს iNaturalist-ის საჯარო დაკვირვებებს, რომლებიც Darevskia rudis obscura-ს სახელითაა შეტანილი, და აღმწერის გარეშე დამატებულ ლოკალიტეტებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მესხური კლდის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-obscura');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-obscura', 'en', 'Obscure rock lizard: where it is recorded in Georgia', 'The obscure rock lizard map combines public iNaturalist observations in Georgia filed as Darevskia rudis obscura with localities that have no observer. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Obscure rock lizard observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-obscura');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-obscura', 'ru', 'Где тёмная скальная ящерица отмечена в Грузии', 'Карта тёмной скальной ящерицы объединяет публичные наблюдения iNaturalist в Грузии, внесённые как Darevskia rudis obscura, и локалитеты без наблюдателя. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения тёмной скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-obscura');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-obscura', 'tr', 'Koyu kayalık kertenkele Gürcistan''da nerede kaydedildi?', 'Koyu kayalık kertenkele haritası, Gürcistan''da Darevskia rudis obscura adıyla girilmiş herkese açık iNaturalist gözlemlerini ve gözlemcisi olmayan lokaliteleri birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Koyu kayalık kertenkele gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-obscura');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-portschinskii', 35384, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-portschinskii');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-portschinskii', 'ka', 'სად არის მტკვრის ხვლიკი დაფიქსირებული საქართველოში', 'მტკვრის ხვლიკის რუკა ატლასის საველე ფოტოებსა და საქართველოში გაკეთებულ iNaturalist-ის საჯარო დაკვირვებებს აერთიანებს. ჩანაწერების რეგიონული ცხრილი დაკვირვებებსა და დადასტურებულ გავრცელებას განასხვავებს: რუკაზე მხოლოდ დადასტურებული სტატუსის მქონე რეგიონი გამოიკვეთება. რეგიონი, სადაც მხოლოდ რამდენიმე ჩანაწერია, ცხრილში ჩანს, მაგრამ გავრცელებად არ ითვლება. iNaturalist-ის მიერ დაფარული კოორდინატი და ამოუცნობი დაკვირვება ამ სტატუსში არ ითვლება. ცალკეული წერტილები დაკვირვების ადგილებს აჩვენებს და არა პოპულაციის სიმჭიდროვეს.', 'მტკვრის ხვლიკის დაკვირვებები და დადასტურებული რეგიონები საქართველოს რუკაზე', 'დადასტურებული რეგიონი', NULL, 'დადასტურებული გავრცელება' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-portschinskii');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-portschinskii', 'en', 'Portschinsky''s lizard: where it is recorded in Georgia', 'The Portschinsky''s lizard map combines atlas field photos with public iNaturalist observations in Georgia. The records-by-region table keeps observations separate from confirmed range: only a region with a confirmed status is shaded. A region with only a few records is listed but not counted as range. iNaturalist coordinates that are obscured and observations still awaiting identification do not count toward that status. Individual points show observation locations, not population density.', 'Portschinsky''s lizard observations and confirmed regions on a map of Georgia', 'Confirmed region', NULL, 'Confirmed distribution' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-portschinskii');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-portschinskii', 'ru', 'Где куринская ящерица отмечена в Грузии', 'Карта куринской ящерицы объединяет полевые фото атласа и публичные наблюдения iNaturalist в Грузии. Таблица записей по регионам отделяет наблюдения от подтверждённого ареала: на карте выделяются только регионы с подтверждённым статусом. Регион, где записей всего несколько, указан в таблице, но не считается частью ареала. Скрытые iNaturalist координаты и наблюдения, ожидающие определения, не учитываются для этого статуса. Отдельные точки показывают места наблюдений, а не плотность популяции.', 'Наблюдения куринской ящерицы и подтверждённые регионы на карте Грузии', 'Подтверждённый регион', NULL, 'Подтверждённое распространение' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-portschinskii');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-portschinskii', 'tr', 'Kura kertenkelesi Gürcistan''da nerede kaydedildi?', 'Kura kertenkelesi haritası atlasın arazi fotoğraflarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgelere göre kayıt tablosu gözlemleri doğrulanmış yayılıştan ayırır: haritada yalnızca doğrulanmış durumundaki bölge taranır. Yalnızca birkaç kaydı olan bölge tabloda görünür, ancak yayılış sayılmaz. iNaturalist''in gizlediği koordinatlar ve henüz tanımlanmamış gözlemler bu duruma sayılmaz. Tekil noktalar gözlem yerlerini gösterir, nüfus yoğunluğunu değil.', 'Kura kertenkelesi gözlemleri ve doğrulanmış bölgeler Gürcistan haritasında', 'Doğrulanmış bölge', NULL, 'Doğrulanmış yayılış' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-portschinskii');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-praticola', 35383, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-praticola');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-praticola', 'ka', 'სად არის მდელოს ხვლიკი დაფიქსირებული საქართველოში', 'მდელოს ხვლიკის რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. ჩანაწერების რეგიონული ცხრილი დაკვირვებებსა და დადასტურებულ გავრცელებას განასხვავებს: რუკაზე მხოლოდ დადასტურებული სტატუსის მქონე რეგიონი გამოიკვეთება. iNaturalist ამ სახეობის ყველა საჯარო კოორდინატს დაახლოებით 28 კმ-ით ფარავს, დაფარული კოორდინატი კი ამ სტატუსში არ ითვლება, ამიტომ რუკაზე ჯერ არცერთი რეგიონი არ არის გამოკვეთილი. iNaturalist კოლხურ მდელოს ხვლიკს (D. pontica) მდელოს ხვლიკის ქვესახეობად განიხილავს, ამიტომ დასავლეთ საქართველოს ჩანაწერები შესაძლოა მას ეკუთვნოდეს. ცალკეული წერტილები დაკვირვების მიახლოებით ადგილებს აჩვენებს და არა პოპულაციის სიმჭიდროვეს.', 'მდელოს ხვლიკის დაკვირვებები და დადასტურებული რეგიონები საქართველოს რუკაზე', 'დადასტურებული რეგიონი', NULL, 'დადასტურებული გავრცელება' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-praticola');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-praticola', 'en', 'Meadow Lizard: where it is recorded in Georgia', 'The Meadow Lizard map uses public iNaturalist observations in Georgia. The records-by-region table keeps observations separate from confirmed range: only a region with a confirmed status is shaded. iNaturalist obscures every public coordinate for this species by about 28 km, and obscured coordinates do not count toward that status, so no region is shaded yet. iNaturalist treats the Pontic Meadow Lizard (D. pontica) as a subspecies of the Meadow Lizard, so records from western Georgia may belong to it. Individual points show approximate observation locations, not population density.', 'Meadow Lizard observations and confirmed regions on a map of Georgia', 'Confirmed region', NULL, 'Confirmed distribution' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-praticola');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-praticola', 'ru', 'Где луговая ящерица отмечена в Грузии', 'Карта луговой ящерицы основана на публичных наблюдениях iNaturalist в Грузии. Таблица записей по регионам отделяет наблюдения от подтверждённого ареала: на карте выделяются только регионы с подтверждённым статусом. iNaturalist скрывает все публичные координаты этого вида примерно на 28 км, а скрытые координаты для этого статуса не учитываются, поэтому пока ни один регион не выделен. iNaturalist рассматривает понтийскую луговую ящерицу (D. pontica) как подвид луговой ящерицы, поэтому записи из западной Грузии могут относиться к ней. Отдельные точки показывают приблизительные места наблюдений, а не плотность популяции.', 'Наблюдения луговой ящерицы и подтверждённые регионы на карте Грузии', 'Подтверждённый регион', NULL, 'Подтверждённое распространение' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-praticola');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-praticola', 'tr', 'Çayır kertenkelesi Gürcistan''da nerede kaydedildi?', 'Çayır kertenkelesi haritası Gürcistan''daki herkese açık iNaturalist gözlemlerine dayanır. Bölgelere göre kayıt tablosu gözlemleri doğrulanmış yayılıştan ayırır: haritada yalnızca doğrulanmış durumundaki bölge taranır. iNaturalist bu türün tüm açık koordinatlarını yaklaşık 28 km gizler ve gizli koordinatlar bu duruma sayılmaz; bu yüzden henüz hiçbir bölge taranmamıştır. iNaturalist Pontik çayır kertenkelesini (D. pontica) çayır kertenkelesinin alt türü olarak ele alır; bu nedenle batı Gürcistan''dan gelen kayıtlar ona ait olabilir. Tekil noktalar yaklaşık gözlem yerlerini gösterir, nüfus yoğunluğunu değil.', 'Çayır kertenkelesi gözlemleri ve doğrulanmış bölgeler Gürcistan haritasında', 'Doğrulanmış bölge', NULL, 'Doğrulanmış yayılış' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-praticola');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'darevskia-valentini', 35362, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'darevskia-valentini');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-valentini', 'ka', 'სად არის ვალენტინის ხვლიკი დაფიქსირებული საქართველოში', 'ვალენტინის ხვლიკის რუკა აერთიანებს ატლასისთვის მოწოდებულ საველე ჩანაწერებსა და საქართველოში გაკეთებულ iNaturalist-ის საჯარო დაკვირვებებს. ჩანაწერების რეგიონული ცხრილი დაკვირვებებსა და დადასტურებულ გავრცელებას განასხვავებს: რუკაზე მხოლოდ დადასტურებული სტატუსის მქონე რეგიონი გამოიკვეთება. iNaturalist-ის მიერ დაფარული კოორდინატი და ამოუცნობი დაკვირვება ამ სტატუსში არ ითვლება. ცალკეული წერტილები დაკვირვების ადგილებს აჩვენებს და არა პოპულაციის სიმჭიდროვეს.', 'ვალენტინის ხვლიკის დაკვირვებები და დადასტურებული რეგიონები საქართველოს რუკაზე', 'დადასტურებული რეგიონი', NULL, 'დადასტურებული გავრცელება' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-valentini');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-valentini', 'en', 'Valentin''s lizard: where it is recorded in Georgia', 'The Valentin''s lizard map combines field records supplied for the atlas with public iNaturalist observations in Georgia. The records-by-region table keeps observations separate from confirmed range: only a region with a confirmed status is shaded. iNaturalist coordinates that are obscured and observations still awaiting identification do not count toward that status. Individual points show observation locations, not population density.', 'Valentin''s lizard observations and confirmed regions on a map of Georgia', 'Confirmed region', NULL, 'Confirmed distribution' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-valentini');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-valentini', 'ru', 'Где ящерица Валентина отмечена в Грузии', 'Карта ящерицы Валентина объединяет полевые записи, предоставленные для атласа, и публичные наблюдения iNaturalist в Грузии. Таблица записей по регионам отделяет наблюдения от подтверждённого ареала: на карте выделяются только регионы с подтверждённым статусом. Скрытые iNaturalist координаты и наблюдения, ожидающие определения, не учитываются для этого статуса. Отдельные точки показывают места наблюдений, а не плотность популяции.', 'Наблюдения ящерицы Валентина и подтверждённые регионы на карте Грузии', 'Подтверждённый регион', NULL, 'Подтверждённое распространение' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-valentini');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'darevskia-valentini', 'tr', 'Valentin kertenkelesi Gürcistan''da nerede kaydedildi?', 'Valentin kertenkelesi haritası atlas için sağlanan arazi kayıtlarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgelere göre kayıt tablosu gözlemleri doğrulanmış yayılıştan ayırır: haritada yalnızca doğrulanmış durumundaki bölge taranır. iNaturalist''in gizlediği koordinatlar ve henüz tanımlanmamış gözlemler bu duruma sayılmaz. Tekil noktalar gözlem yerlerini gösterir, nüfus yoğunluğunu değil.', 'Valentin kertenkelesi gözlemleri ve doğrulanmış bölgeler Gürcistan haritasında', 'Doğrulanmış bölge', NULL, 'Doğrulanmış yayılış' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'darevskia-valentini');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'dendrocopos-major', 17871, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'dendrocopos-major');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'dendrocopos-major', 'ka', 'სად არის დიდი ჭრელი კოდალა დაფიქსირებული საქართველოში', 'დიდი ჭრელი კოდალას რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'დიდი ჭრელი კოდალას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'dendrocopos-major');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'dendrocopos-major', 'en', 'Great spotted woodpecker: where it is recorded in Georgia', 'The great spotted woodpecker map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Great spotted woodpecker observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'dendrocopos-major');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'dendrocopos-major', 'ru', 'Где большой пёстрый дятел отмечен в Грузии', 'Карта большого пёстрого дятла использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения большого пёстрого дятла и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'dendrocopos-major');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'dendrocopos-major', 'tr', 'Orman alaca ağaçkakanı Gürcistan''da nerede kaydedildi?', 'Orman alaca ağaçkakanı haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Orman alaca ağaçkakanı gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'dendrocopos-major');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'dolichophis-schmidti', 73760, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'dolichophis-schmidti');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'dolichophis-schmidti', 'ka', 'სად არის წითელმუცელა მცურავი დაფიქსირებული საქართველოში', 'წითელმუცელა მცურავის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, ხელით დამუშავებულ ლოკალიტეტებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები.', 'წითელმუცელა მცურავის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'dolichophis-schmidti');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'dolichophis-schmidti', 'en', 'Red-bellied racer: where it is recorded in Georgia', 'The red-bellied racer map combines Reptiles.ge editorial photo records, hand-curated localities, and public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'Red-bellied racer distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'dolichophis-schmidti');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'dolichophis-schmidti', 'ru', 'Где краснобрюхий полоз отмечен в Грузии', 'Карта краснобрюхого полоза объединяет редакционные фотозаписи Reptiles.ge, вручную обработанные локалитеты и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте закрашены только регионы с достаточным числом записей.', 'Данные о распространении краснобрюхого полоза и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'dolichophis-schmidti');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'dolichophis-schmidti', 'tr', 'Kırmızı karınlı yılan Gürcistan''da nerede kaydedildi?', 'Kırmızı karınlı yılan haritası Reptiles.ge editoryal fotoğraf kayıtlarını, elle düzenlenmiş lokaliteleri ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler gösterilir.', 'Kırmızı karınlı yılanın Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'dolichophis-schmidti');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'eirenis-collaris', 30290, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'eirenis-collaris');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eirenis-collaris', 'ka', 'სად არის საყელოიანი ეირენისი დაფიქსირებული საქართველოში', 'საყელოიანი ეირენისის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. დაფარული კოორდინატის მქონე ჩანაწერი რეგიონის სტატუსში არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'საყელოიანი ეირენისის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eirenis-collaris');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eirenis-collaris', 'en', 'Collared dwarf snake: where it is recorded in Georgia', 'The collared dwarf snake map uses Reptiles.ge editorial photo records and public iNaturalist observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Records with obscured coordinates do not count towards a region''s status. Record counts reflect observation effort, not population density.', 'Collared dwarf snake observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eirenis-collaris');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eirenis-collaris', 'ru', 'Где ошейниковый эйренис отмечен в Грузии', 'Карта ошейникового эйрениса объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Записи со скрытыми координатами не учитываются в статусе региона. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения ошейникового эйрениса и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eirenis-collaris');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eirenis-collaris', 'tr', 'Yakalı cüce yılan Gürcistan''da nerede kaydedildi?', 'Yakalı cüce yılan haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Koordinatı gizlenmiş kayıtlar bölgenin durumuna sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Yakalı cüce yılan gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eirenis-collaris');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'eirenis-modestus', 30293, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'eirenis-modestus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eirenis-modestus', 'ka', 'სად არის წყნარი ეირენისი დაფიქსირებული საქართველოში', 'წყნარი ეირენისის რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. გამოკვეთილია მხოლოდ ის რეგიონები, რომლებსაც ჩანაწერების რეგიონულ ცხრილში საკმარისი ჩანაწერი აქვთ; ცალკეული ჩანაწერი მთელი რეგიონის გავრცელებას არ ნიშნავს. ზოგი საჯარო კოორდინატი დაფარული ან მიახლოებითია, ამიტომ საზღვართან რეგიონის მიკუთვნება გაურკვეველია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'წყნარი ეირენისის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eirenis-modestus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eirenis-modestus', 'en', 'Ring-headed dwarf snake: where it is recorded in Georgia', 'The ring-headed dwarf snake map uses public iNaturalist observations in Georgia. Only regions with enough records in the records-by-region table are highlighted; isolated records do not establish region-wide distribution. Some public coordinates are obscured or approximate, making assignments near regional borders uncertain. Record counts reflect observation effort, not population density.', 'Ring-headed dwarf snake observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eirenis-modestus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eirenis-modestus', 'ru', 'Где скромный эйренис отмечен в Грузии', 'Карта скромного эйрениса основана на публичных наблюдениях iNaturalist в Грузии. Выделены только регионы с достаточным числом записей в таблице записей; отдельная запись не означает распространение по всему региону. Некоторые публичные координаты скрыты или приблизительны, поэтому привязка точек у границ регионов неопределённа. Число записей отражает активность наблюдателей, не плотность популяции.', 'Наблюдения скромного эйрениса и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eirenis-modestus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eirenis-modestus', 'tr', 'Halkalı başlı cüce yılan Gürcistan''da nerede kaydedildi?', 'Halkalı başlı cüce yılan haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Yalnızca bölgesel kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır; tek bir kayıt tüm bölgede yayılış anlamına gelmez. Bazı halka açık koordinatlar gizlenmiş veya yaklaşıktır; bölge sınırlarına yakın noktaların atanması belirsizdir. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Halkalı başlı cüce yılan gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eirenis-modestus');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'elaphe-urartica', 965955, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'elaphe-urartica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'elaphe-urartica', 'ka', 'სად არის ურარტუს მცურავი დაფიქსირებული საქართველოში', 'ურარტუს მცურავის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ზოგი საჯარო კოორდინატი დაფარული ან მიახლოებითია, ამიტომ საზღვართან მდებარე წერტილი თავისთავად ახალ რეგიონს არ ამატებს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ურარტუს მცურავის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'elaphe-urartica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'elaphe-urartica', 'en', 'Urartian ratsnake: where it is recorded in Georgia', 'The Urartian ratsnake map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Some public coordinates are obscured or approximate, so a point near a border does not by itself add a new region. Record counts reflect observation effort, not population density.', 'Urartian ratsnake observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'elaphe-urartica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'elaphe-urartica', 'ru', 'Где урартский полоз отмечен в Грузии', 'Карта урартского полоза использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Часть публичных координат скрыта или приблизительна, поэтому точка у границы сама по себе не добавляет новый регион. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения урартского полоза и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'elaphe-urartica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'elaphe-urartica', 'tr', 'Urartu sıçanyılanı Gürcistan''da nerede kaydedildi?', 'Urartu sıçanyılanı haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Bazı halka açık koordinatlar gizlenmiş veya yaklaşıktır; sınırdaki bir nokta kendiliğinden yeni bir bölge eklemez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Urartu sıçanyılanı gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'elaphe-urartica');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'emys-orbicularis', 39867, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'emys-orbicularis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'emys-orbicularis', 'ka', 'სად არის ჭაობის კუ დაფიქსირებული საქართველოში', 'ჭაობის კუს რუკა აჩვენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რუკაზე მხოლოდ ის რეგიონებია გამოკვეთილი, რომლებსაც ჩანაწერების ცხრილში საკმარისი ჩანაწერი აქვს. iNaturalist ამ სახეობის საჯარო კოორდინატებს ფარავს, ამიტომ წერტილები მიახლოებითია: ზოგი ზღვაში ან მეზობელ რეგიონში ხვდება, ხოლო რეგიონების საზღვრებს გარეთ მოხვედრილი წერტილები ცხრილში არ ითვლება. გამოკვეთილი რეგიონი არ ნიშნავს მის მთელ ტერიტორიაზე გავრცელებას; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ჭაობის კუს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'emys-orbicularis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'emys-orbicularis', 'en', 'Where European pond turtles are recorded in Georgia', 'The European pond turtle map shows public iNaturalist observations in Georgia. Only regions with enough records in the records table are shaded on the map. iNaturalist obscures the public coordinates of this species, so points are approximate, some fall offshore or across a border, and those outside the region outlines are not counted. A shaded region does not mean the turtle occupies all of it; record counts reflect observation effort, not population density.', 'European pond turtle field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'emys-orbicularis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'emys-orbicularis', 'ru', 'Где европейская болотная черепаха отмечена в Грузии', 'Карта европейской болотной черепахи показывает публичные наблюдения iNaturalist в Грузии. На карте выделены только регионы с достаточным числом записей в таблице записей. iNaturalist скрывает публичные координаты этого вида, поэтому точки приблизительны: некоторые попадают в море или в соседний регион, а точки за границами регионов в таблице не учитываются. Выделенный регион не означает присутствие на всей его территории; число записей не измеряет плотность популяции.', 'Полевые записи европейской болотной черепахи и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'emys-orbicularis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'emys-orbicularis', 'tr', 'Avrupa bataklık kaplumbağası Gürcistan''da nerede kaydedildi?', 'Avrupa bataklık kaplumbağası haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini gösterir. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır. iNaturalist bu türün açık koordinatlarını gizler; bu yüzden noktalar yaklaşıktır, bazıları denize veya komşu bölgeye düşer ve bölge sınırları dışında kalan noktalar tabloda sayılmaz. Vurgulanan bölge türün her yerinde bulunduğu anlamına gelmez; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Avrupa bataklık kaplumbağasının arazi kayıtları ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'emys-orbicularis');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'eremias-velox', 36012, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'eremias-velox');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eremias-velox', 'ka', 'სად არის მარდი ფსვენი დაფიქსირებული საქართველოში', 'მარდი ფსვენის რუკა აერთიანებს ატლასისთვის მოწოდებულ საველე ფოტოებსა და საქართველოში გაკეთებულ iNaturalist-ის საჯარო დაკვირვებებს. ჩანაწერების რეგიონული ცხრილი დაკვირვებებსა და დადასტურებულ გავრცელებას განასხვავებს: რუკაზე მხოლოდ დადასტურებული სტატუსის მქონე რეგიონი გამოიკვეთება. რეგიონი, სადაც მხოლოდ რამდენიმე ჩანაწერია, ცხრილში ჩანს, მაგრამ გავრცელებად არ ითვლება. iNaturalist-ის მიერ დაფარული კოორდინატი და ამოუცნობი დაკვირვება ამ სტატუსში არ ითვლება. ცალკეული წერტილები დაკვირვების ადგილებს აჩვენებს და არა პოპულაციის სიმჭიდროვეს.', 'მარდი ფსვენის დაკვირვებები და დადასტურებული რეგიონები საქართველოს რუკაზე', 'დადასტურებული რეგიონი', NULL, 'დადასტურებული გავრცელება' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eremias-velox');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eremias-velox', 'en', 'Rapid racerunner: where it is recorded in Georgia', 'The rapid racerunner map combines field photos supplied for the atlas with public iNaturalist observations in Georgia. The records-by-region table keeps observations separate from confirmed range: only a region with a confirmed status is shaded. A region with only a few records is listed but not counted as range. iNaturalist coordinates that are obscured and observations still awaiting identification do not count toward that status. Individual points show observation locations, not population density.', 'Rapid racerunner observations and confirmed regions on a map of Georgia', 'Confirmed region', NULL, 'Confirmed distribution' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eremias-velox');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eremias-velox', 'ru', 'Где быстрая ящурка отмечена в Грузии', 'Карта быстрой ящурки объединяет полевые фотографии, предоставленные для атласа, и публичные наблюдения iNaturalist в Грузии. Таблица записей по регионам отделяет наблюдения от подтверждённого ареала: на карте выделяются только регионы с подтверждённым статусом. Регион, где записей всего несколько, указан в таблице, но не считается частью ареала. Скрытые iNaturalist координаты и наблюдения, ожидающие определения, не учитываются для этого статуса. Отдельные точки показывают места наблюдений, а не плотность популяции.', 'Наблюдения быстрой ящурки и подтверждённые регионы на карте Грузии', 'Подтверждённый регион', NULL, 'Подтверждённое распространение' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eremias-velox');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'eremias-velox', 'tr', 'Hızlı koşar kertenkele Gürcistan''da nerede kaydedildi?', 'Hızlı koşar kertenkele haritası atlas için sağlanan arazi fotoğraflarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgelere göre kayıt tablosu gözlemleri doğrulanmış yayılıştan ayırır: haritada yalnızca doğrulanmış durumundaki bölge taranır. Yalnızca birkaç kaydı olan bölge tabloda görünür, ancak yayılış sayılmaz. iNaturalist''in gizlediği koordinatlar ve henüz tanımlanmamış gözlemler bu duruma sayılmaz. Tekil noktalar gözlem yerlerini gösterir, nüfus yoğunluğunu değil.', 'Hızlı koşar kertenkele gözlemleri ve doğrulanmış bölgeler Gürcistan haritasında', 'Doğrulanmış bölge', NULL, 'Doğrulanmış yayılış' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'eremias-velox');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'erithacus-rubecula', 13094, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'erithacus-rubecula');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'erithacus-rubecula', 'ka', 'სად არის გულწითელა დაფიქსირებული საქართველოში', 'გულწითელას რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'გულწითელას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'erithacus-rubecula');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'erithacus-rubecula', 'en', 'European robin: where it is recorded in Georgia', 'The European robin map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'European robin observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'erithacus-rubecula');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'erithacus-rubecula', 'ru', 'Где зарянка отмечена в Грузии', 'Карта зарянки использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения зарянки и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'erithacus-rubecula');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'erithacus-rubecula', 'tr', 'Kızılgerdan Gürcistan''da nerede kaydedildi?', 'Kızılgerdan haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kızılgerdan gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'erithacus-rubecula');
