INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'euscorpius-italicus', 'ka', 'სად არის იტალიური მორიელი დაფიქსირებული საქართველოში', 'იტალიური მორიელის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, Georgian Biodiversity Database-ის ლოკალიტეტებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'იტალიური მორიელის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'euscorpius-italicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'euscorpius-italicus', 'en', 'Italian scorpion: where it is recorded in Georgia', 'The Italian scorpion map combines Reptiles.ge editorial photo records, Georgian Biodiversity Database localities, and public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'Italian scorpion distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'euscorpius-italicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'euscorpius-italicus', 'ru', 'Где итальянский скорпион отмечен в Грузии', 'Карта итальянского скорпиона объединяет редакционные фотозаписи Reptiles.ge, локалитеты Georgian Biodiversity Database и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении итальянского скорпиона и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'euscorpius-italicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'euscorpius-italicus', 'tr', 'İtalyan akrebi Gürcistan''da nerede kaydedildi?', 'İtalyan akrebi haritası Reptiles.ge editoryal fotoğraf kayıtlarını, Georgian Biodiversity Database lokalitelerini ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'İtalyan akrebinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'euscorpius-italicus');
