INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'euscorpius-mingrelicus', 'ka', 'სად არის მეგრული მორიელი დაფიქსირებული საქართველოში', 'მეგრული მორიელის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'მეგრული მორიელის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'euscorpius-mingrelicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'euscorpius-mingrelicus', 'en', 'Mingrelian scorpion: where it is recorded in Georgia', 'The Mingrelian scorpion map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'Mingrelian scorpion distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'euscorpius-mingrelicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'euscorpius-mingrelicus', 'ru', 'Где мингрельский скорпион отмечен в Грузии', 'Карта мингрельского скорпиона объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении мингрельского скорпиона и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'euscorpius-mingrelicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'euscorpius-mingrelicus', 'tr', 'Karadeniz akrebi Gürcistan''da nerede kaydedildi?', 'Karadeniz akrebi haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'Karadeniz akrebinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'euscorpius-mingrelicus');
