INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'gyps-fulvus', 'en', 'Griffon vulture: where it is recorded in Georgia', 'The griffon vulture map uses public iNaturalist observations from Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions have too few records. Observations do not by themselves confirm nesting. Record counts reflect observation effort, not population density.', 'Griffon vulture observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'gyps-fulvus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'gyps-fulvus', 'ru', 'Где белоголовый сип отмечен в Грузии', 'Карта белоголового сипа основана на публичных наблюдениях iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей, в остальных регионах записей мало. Наблюдения сами по себе не подтверждают гнездование. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения белоголового сипа и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'gyps-fulvus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'gyps-fulvus', 'tr', 'Kızıl akbaba Gürcistan''da nerede kaydedildi?', 'Kızıl akbaba haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan gelir: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğerlerinde kayıt azdır. Gözlemler tek başına üremeyi doğrulamaz. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Kızıl akbaba gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'gyps-fulvus');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'halyomorpha-halys', 81923, NULL, NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'halyomorpha-halys');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'hemorrhois-ravergieri', 102628, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'hemorrhois-ravergieri');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'hemorrhois-ravergieri', 'ka', 'სად არის ნაირფერი მცურავი დაფიქსირებული საქართველოში', 'ნაირფერი მცურავის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, საქართველოს საველე ლოკალიტეტებსა და iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. iNaturalist-ის დაკვირვებები, რომელთა ამოცნობა ჯერ დადასტურებული არ არის, რუკაზე ჩანს, მაგრამ არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ნაირფერი მცურავის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'hemorrhois-ravergieri');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'hemorrhois-ravergieri', 'en', 'Spotted Whip Snake: where it is recorded in Georgia', 'The Spotted Whip Snake map combines Reptiles.ge editorial photo records, field localities from Georgia and public iNaturalist photo observations. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. iNaturalist observations that still need an ID are shown but not counted. Record counts reflect observation effort, not population density.', 'Spotted Whip Snake observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'hemorrhois-ravergieri');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'hemorrhois-ravergieri', 'ru', 'Где пятнистый полоз отмечен в Грузии', 'Карта пятнистого полоза объединяет редакционные фотозаписи Reptiles.ge, полевые локалитеты из Грузии и публичные фотонаблюдения iNaturalist. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Наблюдения iNaturalist, которым ещё нужно подтверждение определения, показаны, но не учитываются. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения пятнистого полоза и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'hemorrhois-ravergieri');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'hemorrhois-ravergieri', 'tr', 'Benekli kamçı yılanı Gürcistan''da nerede kaydedildi?', 'Benekli kamçı yılanı haritası Reptiles.ge editoryal fotoğraf kayıtlarını, Gürcistan''daki arazi lokalitelerini ve herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Tür teşhisi henüz doğrulanmamış iNaturalist gözlemleri gösterilir ama sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Benekli kamçı yılanı gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'hemorrhois-ravergieri');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'hyla-orientalis', 70647, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'hyla-orientalis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'hyla-orientalis', 'ka', 'სად არის აღმოსავლური ვასაკა დაფიქსირებული საქართველოში', 'აღმოსავლური ვასაკას რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. ჩანაწერების რეგიონული ცხრილი დაკვირვებებსა და დადასტურებულ გავრცელებას განასხვავებს: რუკაზე მხოლოდ დადასტურებული სტატუსის მქონე რეგიონი გამოიკვეთება. რეგიონი, სადაც მხოლოდ რამდენიმე ჩანაწერია, ცხრილში ჩანს, მაგრამ გავრცელებად არ ითვლება. iNaturalist-ის მიერ დაფარული კოორდინატი, ამოუცნობი დაკვირვება და თარიღის გარეშე შემთხვევითი დაკვირვება ამ სტატუსში არ ითვლება. ცალკეული წერტილები დაკვირვების ადგილებს აჩვენებს და არა პოპულაციის სიმჭიდროვეს.', 'აღმოსავლური ვასაკას დაკვირვებები და დადასტურებული რეგიონები საქართველოს რუკაზე', 'დადასტურებული რეგიონი', NULL, 'დადასტურებული გავრცელება' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'hyla-orientalis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'hyla-orientalis', 'en', 'Eastern Treefrog: where it is recorded in Georgia', 'The Eastern Treefrog map uses public iNaturalist observations in Georgia. The records-by-region table keeps observations separate from confirmed range: only a region with a confirmed status is shaded. A region with only a few records is listed but not counted as range. iNaturalist coordinates that are obscured, observations still awaiting identification and undated casual observations do not count toward that status. Individual points show observation locations, not population density.', 'Eastern Treefrog observations and confirmed regions on a map of Georgia', 'Confirmed region', NULL, 'Confirmed distribution' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'hyla-orientalis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'hyla-orientalis', 'ru', 'Где восточная квакша отмечена в Грузии', 'Карта восточной квакши основана на публичных наблюдениях iNaturalist в Грузии. Таблица записей по регионам отделяет наблюдения от подтверждённого ареала: на карте выделяются только регионы с подтверждённым статусом. Регион, где записей всего несколько, указан в таблице, но не считается частью ареала. Скрытые iNaturalist координаты, наблюдения, ожидающие определения, и случайные наблюдения без даты не учитываются для этого статуса. Отдельные точки показывают места наблюдений, а не плотность популяции.', 'Наблюдения восточной квакши и подтверждённые регионы на карте Грузии', 'Подтверждённый регион', NULL, 'Подтверждённое распространение' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'hyla-orientalis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'hyla-orientalis', 'tr', 'Doğu ağaç kurbağası Gürcistan''da nerede kaydedildi?', 'Doğu ağaç kurbağası haritası Gürcistan''daki herkese açık iNaturalist gözlemlerine dayanır. Bölgelere göre kayıt tablosu gözlemleri doğrulanmış yayılıştan ayırır: haritada yalnızca doğrulanmış durumundaki bölge taranır. Yalnızca birkaç kaydı olan bölge tabloda görünür, ancak yayılış sayılmaz. iNaturalist''in gizlediği koordinatlar, henüz tanımlanmamış gözlemler ve tarihsiz rastgele gözlemler bu duruma sayılmaz. Tekil noktalar gözlem yerlerini gösterir, nüfus yoğunluğunu değil.', 'Doğu ağaç kurbağası gözlemleri ve doğrulanmış bölgeler Gürcistan haritasında', 'Doğrulanmış bölge', NULL, 'Doğrulanmış yayılış' WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'hyla-orientalis');
