INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'jynx-torquilla', 'en', 'Eurasian wryneck: where it is recorded in Georgia', 'The Eurasian wryneck map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Record counts reflect observation effort, not population density.', 'Eurasian wryneck observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'jynx-torquilla');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'jynx-torquilla', 'ru', 'Где вертишейка отмечена в Грузии', 'Карта вертишейки использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения вертишейки и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'jynx-torquilla');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'jynx-torquilla', 'tr', 'Boyunçeviren Gürcistan''da nerede kaydedildi?', 'Boyunçeviren haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Boyunçeviren gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'jynx-torquilla');
