INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lacerta-agilis', 'ka', 'სად არის მარდი ხვლიკი დაფიქსირებული საქართველოში', 'მარდი ხვლიკის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მარდი ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lacerta-agilis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lacerta-agilis', 'en', 'Sand lizard: where it is recorded in Georgia', 'The sand lizard map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Record counts reflect observation effort, not population density.', 'Sand lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lacerta-agilis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lacerta-agilis', 'ru', 'Где прыткая ящерица отмечена в Грузии', 'Карта прыткой ящерицы использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения прыткой ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lacerta-agilis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lacerta-agilis', 'tr', 'Kum kertenkelesi Gürcistan''da nerede kaydedildi?', 'Kum kertenkelesi haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kum kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lacerta-agilis');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'lacerta-media', 73839, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'lacerta-media');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lacerta-media', 'ka', 'სად არის საშუალო ხვლიკი დაფიქსირებული საქართველოში', 'საშუალო ხვლიკის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. დაფარული კოორდინატის ან დაუდასტურებელი სარკვევის მქონე ჩანაწერი რეგიონის სტატუსში არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'საშუალო ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lacerta-media');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lacerta-media', 'en', 'Caucasian green lizard: where it is recorded in Georgia', 'The Caucasian green lizard map uses Reptiles.ge editorial photo records and public iNaturalist observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Records with obscured coordinates or without a research-grade identification do not count towards a region''s status. Record counts reflect observation effort, not population density.', 'Caucasian green lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lacerta-media');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lacerta-media', 'ru', 'Где кавказская зелёная ящерица отмечена в Грузии', 'Карта кавказской зелёной ящерицы объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Записи со скрытыми координатами или без подтверждённого определения не учитываются в статусе региона. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения кавказской зелёной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lacerta-media');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lacerta-media', 'tr', 'Kafkas yeşil kertenkelesi Gürcistan''da nerede kaydedildi?', 'Kafkas yeşil kertenkelesi haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Koordinatı gizlenmiş ya da tanımı doğrulanmamış kayıtlar bölgenin durumuna sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kafkas yeşil kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lacerta-media');
