INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lacerta-strigata', 'en', 'Striped lizard: where it is recorded in Georgia', 'The striped lizard map uses Reptiles.ge editorial photo records and public iNaturalist observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Record counts reflect observation effort, not population density.', 'Striped lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lacerta-strigata');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lacerta-strigata', 'ru', 'Где полосатая ящерица отмечена в Грузии', 'Карта полосатой ящерицы объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения полосатой ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lacerta-strigata');
