INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'latrodectus-tredecimguttatus', 'ka', 'სად არის ყარაყურთი დაფიქსირებული საქართველოში', 'ყარაყურთის რუკის რეგიონები ჩანაწერების რეგიონული ცხრილიდანაა. ერთი ჩანაწერიც საკმარისია, რომ რეგიონი რუკაზე გამოიკვეთოს; ჩანაწერის არმქონე რეგიონი არ გამოიკვეთება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ყარაყურთის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'latrodectus-tredecimguttatus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'latrodectus-tredecimguttatus', 'en', 'Mediterranean black widow: where it is recorded in Georgia', 'The Mediterranean black widow map takes regions from its records-by-region table. One record is enough for a region to be shaded on the map; a region with no records is not shaded. Record counts reflect observation effort, not population density.', 'Mediterranean black widow observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'latrodectus-tredecimguttatus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'latrodectus-tredecimguttatus', 'ru', 'Где каракурт отмечен в Грузии', 'Регионы карты каракурта взяты из таблицы записей по регионам. Одной записи достаточно, чтобы регион был выделен на карте; регион без записей не выделяется. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения каракурта и регионы с записями на карте Грузии', 'Регион с записями', 'региона с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'latrodectus-tredecimguttatus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'latrodectus-tredecimguttatus', 'tr', 'Karakurt Gürcistan''da nerede kaydedildi?', 'Karakurt haritasının bölgeleri, bölgelere göre kayıt tablosundan alınır. Bir bölgenin haritada vurgulanması için tek bir kayıt yeterlidir; kaydı olmayan bölge vurgulanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Karakurt gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'latrodectus-tredecimguttatus');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'lutra-lutra', 41850, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'lutra-lutra');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lutra-lutra', 'ka', 'სად არის წავი დაფიქსირებული საქართველოში', 'წავის რუკა აერთიანებს Reptiles.ge-ის მიერ წყაროებიდან დამუშავებულ საველე ლოკალიტეტებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი და ცოტა ჩანაწერის მქონე რეგიონებს.', 'წავის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lutra-lutra');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lutra-lutra', 'en', 'Eurasian otter: where it is recorded in Georgia', 'The Eurasian otter map combines source-derived field localities curated by Reptiles.ge with public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'Eurasian otter distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lutra-lutra');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lutra-lutra', 'ru', 'Где выдра отмечена в Грузии', 'Карта выдры объединяет полевые локалитеты, обработанные Reptiles.ge из источников, и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении выдры и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lutra-lutra');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'lutra-lutra', 'tr', 'Su samuru Gürcistan''da nerede kaydedildi?', 'Su samuru haritası Reptiles.ge tarafından kaynaklardan işlenen arazi lokalitelerini ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olanlardan ayırır.', 'Su samurunun Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'lutra-lutra');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'macrovipera-lebetina', 105083, NULL, NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'macrovipera-lebetina');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'macrovipera-lebetina', 'ka', 'სად გვხვდება გიურზა საქართველოში', 'გიურზას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. წყაროებით დადასტურებული რეგიონები და ინდივიდუალური საველე ჩანაწერები ცალკე ფენებია; ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვედ არ უნდა განვიხილოთ.', 'გიურზას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'macrovipera-lebetina');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'macrovipera-lebetina', 'en', 'Levantine viper: where it occurs in Georgia', 'The Levantine viper map combines Reptiles.ge editorial photo records with public iNaturalist observations. Source-confirmed regions and individual field records are separate layers, and record counts reflect observation effort rather than population density.', 'Levantine viper distribution evidence and field records on a map of Georgia', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'macrovipera-lebetina');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'macrovipera-lebetina', 'ru', 'Где встречается гюрза в Грузии', 'Карта гюрзы объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы, подтверждённые источниками, и отдельные полевые записи показаны разными слоями; количество записей отражает интенсивность наблюдений, а не плотность популяции.', 'Данные о распространении гюрзы и полевые записи на карте Грузии', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'macrovipera-lebetina');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'macrovipera-lebetina', 'tr', 'Levant engereği Gürcistan''da nerede görülür?', 'Levant engereği haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Kaynakla doğrulanmış bölgeler ile tekil arazi kayıtları ayrı katmanlardır; kayıt sayısı gözlem yoğunluğunu yansıtır, popülasyon yoğunluğu değildir.', 'Levant engereğinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'macrovipera-lebetina');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'mantis-religiosa', 53905, NULL, NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'mantis-religiosa');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mantis-religiosa', 'ka', 'სად არის ჩოქელა დაფიქსირებული საქართველოში', 'ჩოქელას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. ინდივიდუალური საველე ჩანაწერები წერტილებადაა ნაჩვენები; ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვედ არ უნდა განვიხილოთ.', 'ჩოქელას საველე ჩანაწერები საქართველოს რუკაზე', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mantis-religiosa');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mantis-religiosa', 'en', 'European mantis: where it is recorded in Georgia', 'The European mantis map combines Reptiles.ge editorial photo records with public iNaturalist observations. Individual field records are shown as point data, and record counts reflect observation effort rather than population density.', 'European mantis field records on a map of Georgia', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mantis-religiosa');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mantis-religiosa', 'ru', 'Где богомол отмечен в Грузии', 'Карта богомола объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Отдельные полевые записи показаны точками; количество записей отражает интенсивность наблюдений, а не плотность популяции.', 'Полевые записи богомола на карте Грузии', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mantis-religiosa');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mantis-religiosa', 'tr', 'Peygamberdevesi Gürcistan''da nerede kaydedildi?', 'Peygamberdevesi haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Tekil arazi kayıtları nokta verisi olarak gösterilir; kayıt sayısı gözlem yoğunluğunu yansıtır, popülasyon yoğunluğu değildir.', 'Peygamberdevesi arazi kayıtları Gürcistan haritasında', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mantis-religiosa');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'mauremys-caspica', 39972, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'mauremys-caspica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mauremys-caspica', 'ka', 'სად არის კასპიური კუ დაფიქსირებული საქართველოში', 'კასპიური კუს რუკა აჩვენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რუკაზე მხოლოდ ის რეგიონებია გამოკვეთილი, რომლებსაც ჩანაწერების ცხრილში საკმარისი ჩანაწერი აქვს. ზოგი საჯარო კოორდინატი დაფარული ან მიახლოებითია, ზოგჯერ კი ლოკალიტეტის ტექსტი წერტილის რეგიონს არ ემთხვევა. გამოკვეთილი რეგიონი არ ნიშნავს მის მთელ ტერიტორიაზე გავრცელებას; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'კასპიური კუს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mauremys-caspica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mauremys-caspica', 'en', 'Where Caspian turtles are recorded in Georgia', 'The Caspian turtle map shows public iNaturalist observations in Georgia. Only regions with enough records in the records table are shaded on the map. Some public coordinates are obscured or approximate, and locality text can disagree with a point''s region. A shaded region does not mean the turtle occupies all of it; record counts reflect observation effort, not population density.', 'Caspian turtle field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mauremys-caspica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mauremys-caspica', 'ru', 'Где каспийская черепаха отмечена в Грузии', 'Карта каспийской черепахи показывает публичные наблюдения iNaturalist в Грузии. На карте выделены только регионы с достаточным числом записей в таблице записей. Некоторые публичные координаты скрыты или приблизительны, а текст местонахождения иногда не совпадает с регионом точки. Выделенный регион не означает присутствие на всей его территории; число записей не измеряет плотность популяции.', 'Полевые записи каспийской черепахи и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mauremys-caspica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mauremys-caspica', 'tr', 'Hazar kaplumbağası Gürcistan''da nerede kaydedildi?', 'Hazar kaplumbağası haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini gösterir. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır. Bazı açık koordinatlar gizlenmiş veya yaklaşıktır; yer adı bazen noktanın bulunduğu bölgeyle uyuşmaz. Vurgulanan bölge türün her yerinde bulunduğu anlamına gelmez; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Hazar kaplumbağasının arazi kayıtları ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mauremys-caspica');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'meles-canescens', 855298, 'record-summary', 1 WHERE EXISTS (SELECT 1 FROM species WHERE id = 'meles-canescens');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'meles-canescens', 'ka', 'სად არის მაჩვი დაფიქსირებული საქართველოში', 'მაჩვის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. რეგიონული პოლიგონების გარეთ დარჩენილი წერტილები საერთო რაოდენობაში შედის, მაგრამ რეგიონს არ მიეკუთვნება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მაჩვის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'meles-canescens');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'meles-canescens', 'en', 'Where the Caucasian badger is recorded in Georgia', 'The Caucasian badger map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Points outside the regional polygons stay in the total but are not assigned to a region. Record counts reflect observation effort, not population density.', 'Caucasian badger observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'meles-canescens');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'meles-canescens', 'ru', 'Где кавказский барсук отмечен в Грузии', 'Карта кавказского барсука использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Точки вне региональных полигонов входят в общее число, но к региону не относятся. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения кавказского барсука и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'meles-canescens');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'meles-canescens', 'tr', 'Kafkas porsuğu Gürcistan''da nerede kaydedildi?', 'Kafkas porsuğu haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Bölge poligonlarının dışında kalan noktalar toplama girer ama bir bölgeye yazılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kafkas porsuğu gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'meles-canescens');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'mertensiella-caucasica', 27853, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'mertensiella-caucasica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mertensiella-caucasica', 'ka', 'სად არის კავკასიური სალამანდრა დაფიქსირებული საქართველოში', '2026 წლის ჩამონათვალში დასახელებული ლოკალიტეტები ადასტურებს ჩანაწერებს აჭარაში, გურიაში, სამცხე–ჯავახეთსა და შიდა ქართლში. დადასტურებული სტატუსის საფუძველი ეს წყაროა და არა დაკვირვებების რაოდენობა. iNaturalist M. djanaschvilii-ს ცალკე ტაქსონად აჩვენებს, ამიტომ აქ მხოლოდ iNaturalist-ის M. caucasica ტაქსონის ჩანაწერებია. საჯარო კოორდინატები დაახლოებით 27 კმ-ითაა დაფარული; წერტილები და მათი რეგიონული დათვლა მიახლოებითია და საზღვარს შეიძლება გადასცდეს. რაოდენობა არც პოპულაციის სიმჭიდროვეს ზომავს და არც მთელი რეგიონის უწყვეტ გავრცელებას ნიშნავს.', 'კავკასიური სალამანდრას წყაროთი დადასტურებული რეგიონები და მიახლოებითი დაკვირვებები საქართველოს რუკაზე', 'წყაროთი დადასტურებული გავრცელების რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mertensiella-caucasica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mertensiella-caucasica', 'en', 'Caucasian salamander: where it is documented in Georgia', 'The 2026 checklist names sites in Adjara, Guria, Samtskhe–Javakheti and Shida Kartli. These named localities, not observation counts, support the confirmed regions. iNaturalist lists M. djanaschvilii separately, so these records cover only iNaturalist''s M. caucasica taxon. Public coordinates are obscured by roughly 27 km; plotted points and their region counts are approximate and may cross borders. Counts reflect observations, not population density or a range across each whole region.', 'Caucasian salamander source-confirmed regions and approximate observations on a map of Georgia', 'Source-confirmed distribution region', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mertensiella-caucasica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mertensiella-caucasica', 'ru', 'Где кавказская саламандра отмечена в Грузии', 'В чек-листе 2026 года названы местонахождения в Аджарии, Гурии, Самцхе–Джавахети и Шида-Картли. Статус подтверждённых регионов основан на этих местонахождениях, а не на числе наблюдений. iNaturalist учитывает M. djanaschvilii отдельно, поэтому здесь показаны записи только таксона M. caucasica по iNaturalist. Публичные координаты скрыты примерно на 27 км; точки и их распределение по регионам приблизительны и могут пересекать границы. Число записей не измеряет плотность популяции и не означает сплошное распространение по всему региону.', 'Подтверждённые источником регионы и приблизительные наблюдения кавказской саламандры на карте Грузии', 'Регион распространения, подтверждённый источником', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mertensiella-caucasica');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mertensiella-caucasica', 'tr', 'Kafkas semenderi Gürcistan''da nerede kaydedildi?', '2026 kontrol listesi Acara, Guria, Samtshe–Cavaheti ve Şida Kartli''de belirli lokaliteler bildirir. Doğrulanmış bölge durumu gözlem sayısına değil, bu lokalitelere dayanır. iNaturalist M. djanaschvilii''yi ayrı listeler; burada yalnızca M. caucasica taksonunun kayıtları vardır. Herkese açık koordinatlar yaklaşık 27 km gizlenmiştir; noktalar ve bölgesel sayımları yaklaşıktır ve sınırları aşabilir. Kayıt sayısı popülasyon yoğunluğunu ya da bütün bölgeye yayılışı göstermez.', 'Kafkas semenderinin kaynakla doğrulanmış bölgeleri ve yaklaşık gözlemleri Gürcistan haritasında', 'Kaynakla doğrulanmış yayılış bölgesi', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mertensiella-caucasica');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'mesobuthus-eupeus', 709915, NULL, NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'mesobuthus-eupeus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mesobuthus-eupeus', 'ka', 'სად არის ჭრელი მორიელი დაფიქსირებული საქართველოში', 'ჭრელი მორიელის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. წყაროებით დადასტურებული რეგიონები და ინდივიდუალური საველე ჩანაწერები ცალკე ფენებია; ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვედ არ უნდა განვიხილოთ.', 'ჭრელი მორიელის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mesobuthus-eupeus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mesobuthus-eupeus', 'en', 'Mottled scorpion: where it is recorded in Georgia', 'The mottled scorpion map combines Reptiles.ge editorial photo records with public iNaturalist observations. Source-confirmed regions and individual field records are separate layers, and record counts reflect observation effort rather than population density.', 'Mottled scorpion distribution evidence and field records on a map of Georgia', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mesobuthus-eupeus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mesobuthus-eupeus', 'ru', 'Где пёстрый скорпион отмечен в Грузии', 'Карта пёстрого скорпиона объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы, подтверждённые источниками, и отдельные полевые записи показаны разными слоями; количество записей отражает интенсивность наблюдений, а не плотность популяции.', 'Данные о распространении пёстрого скорпиона и полевые записи на карте Грузии', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mesobuthus-eupeus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mesobuthus-eupeus', 'tr', 'Alacalı akrep Gürcistan''da nerede kaydedildi?', 'Alacalı akrep haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Kaynakla doğrulanmış bölgeler ile tekil arazi kayıtları ayrı katmanlardır; kayıt sayısı gözlem yoğunluğunu yansıtır, popülasyon yoğunluğu değildir.', 'Alacalı akrebin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', NULL, NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mesobuthus-eupeus');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'mustela-nivalis', 569428, 'record-summary', 1 WHERE EXISTS (SELECT 1 FROM species WHERE id = 'mustela-nivalis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mustela-nivalis', 'ka', 'სად არის დედოფალა დაფიქსირებული საქართველოში', 'დედოფალას რუკა აერთიანებს Reptiles.ge-ის საველე ფოტოებსა და iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან; ამ სახეობაზე ერთი ჩანაწერიც საკმარისია, რომ რეგიონი რუკაზე გამოიკვეთოს. გამოკვეთილი რეგიონი მის მთელ ტერიტორიაზე არსებობას არ ნიშნავს, ხოლო ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვე არ არის.', 'დედოფალას ფოტოდაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mustela-nivalis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mustela-nivalis', 'en', 'Least weasel: where it is recorded in Georgia', 'The least weasel map combines Reptiles.ge field photos with public iNaturalist photo observations. Regions come from the records-by-region table; for this species, one record is enough for a region to be shaded on the map. A highlighted region does not imply presence throughout it, and record counts do not measure population density.', 'Least weasel photo observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mustela-nivalis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mustela-nivalis', 'ru', 'Где ласка отмечена в Грузии', 'Карта ласки объединяет полевые фотографии Reptiles.ge и публичные фотонаблюдения iNaturalist. Регионы взяты из таблицы записей; для этого вида одной записи достаточно, чтобы регион был выделен на карте. Выделенный регион не означает присутствия на всей его территории, а число записей не измеряет плотность популяции.', 'Фотонаблюдения ласки и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mustela-nivalis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'mustela-nivalis', 'tr', 'Gelincik Gürcistan''da nerede kaydedildi?', 'Gelincik haritası Reptiles.ge arazi fotoğraflarını ve herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler kayıt tablosundan alınır; bu türde bir bölgenin haritada vurgulanması için tek bir kayıt yeterlidir. Vurgulanan bölge türün her yerinde bulunduğu anlamına gelmez; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Gelincik fotoğraflı gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'mustela-nivalis');
