INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'natrix-tessellata', 'ka', 'სად არის წყლის ანკარა დაფიქსირებული საქართველოში', 'წყლის ანკარის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი.', 'წყლის ანკარის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'natrix-tessellata');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'natrix-tessellata', 'en', 'Dice snake: where it is recorded in Georgia', 'The dice snake map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'Dice snake distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'natrix-tessellata');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'natrix-tessellata', 'ru', 'Где водяной уж отмечен в Грузии', 'Карта водяного ужа объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте выделены только регионы с достаточным числом записей.', 'Данные о распространении водяного ужа и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'natrix-tessellata');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'natrix-tessellata', 'tr', 'Kareli yılan Gürcistan''da nerede kaydedildi?', 'Kareli yılan haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler vurgulanır.', 'Kareli yılanın Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'natrix-tessellata');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'neophron-percnopterus', 5361, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'neophron-percnopterus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'neophron-percnopterus', 'ka', 'სად არის ფასკუნჯი დაფიქსირებული საქართველოში', 'ფასკუნჯის რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებსა და სარედაქციო ფოტოჩანაწერებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი, დანარჩენში ჩანაწერები ცოტაა. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ფასკუნჯის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'neophron-percnopterus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'neophron-percnopterus', 'en', 'Egyptian vulture: where it is recorded in Georgia', 'The Egyptian vulture map uses public iNaturalist observations from Georgia together with editorial photo records. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions have too few records. Record counts reflect observation effort, not population density.', 'Egyptian vulture observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'neophron-percnopterus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'neophron-percnopterus', 'ru', 'Где стервятник отмечен в Грузии', 'Карта стервятника основана на публичных наблюдениях iNaturalist в Грузии и редакционных фотозаписях. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей, в остальных записей мало. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения стервятника и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'neophron-percnopterus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'neophron-percnopterus', 'tr', 'Küçük akbaba Gürcistan''da nerede kaydedildi?', 'Küçük akbaba haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini ve editoryal fotoğraf kayıtlarını kullanır. Bölgeler, bölgelere göre kayıt tablosundan gelir: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; diğerlerinde kayıt azdır. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Küçük akbaba gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'neophron-percnopterus');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'ommatotriton-ophryticus', 64364, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'ommatotriton-ophryticus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ommatotriton-ophryticus', 'ka', 'სად არის კავკასიური ტრიტონი დაფიქსირებული საქართველოში', 'კავკასიური ტრიტონის რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. iNaturalist ამ სახეობის ყველა საჯარო კოორდინატს დაახლოებით 20 კმ-იან უჯრაში ფარავს, ამიტომ წერტილი მიახლოებითია. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. ჩანაწერი, რომლის დაფარული უჯრა რეგიონის საზღვარს კვეთს, და დაკვირვება, რომლის ამოცნობა ჯერ დადასტურებული არ არის, რუკაზე ჩანს, მაგრამ არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'კავკასიური ტრიტონის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ommatotriton-ophryticus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ommatotriton-ophryticus', 'en', 'Northern Banded Newt: where it is recorded in Georgia', 'The Northern Banded Newt map uses public iNaturalist photo observations in Georgia. iNaturalist obscures every public coordinate for this species within a cell of about 20 km, so a point is approximate. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. A record whose obscured cell crosses a regional border, and an observation that still needs an ID, is shown but not counted. Record counts reflect observation effort, not population density.', 'Northern Banded Newt observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ommatotriton-ophryticus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ommatotriton-ophryticus', 'ru', 'Где северный полосатый тритон отмечен в Грузии', 'Карта северного полосатого тритона основана на публичных фотонаблюдениях iNaturalist в Грузии. iNaturalist скрывает все публичные координаты этого вида в ячейке около 20 км, поэтому точка приблизительна. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Запись, скрытая ячейка которой пересекает границу региона, и наблюдение, которому ещё нужно подтверждение определения, показаны, но не учитываются. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения северного полосатого тритона и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ommatotriton-ophryticus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ommatotriton-ophryticus', 'tr', 'Kuzey şeritli semender Gürcistan''da nerede kaydedildi?', 'Kuzey şeritli semender haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. iNaturalist bu türün tüm açık koordinatlarını yaklaşık 20 km''lik bir hücre içinde gizler, bu yüzden nokta yaklaşıktır. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Gizli hücresi bölge sınırını kesen kayıt ve tür teşhisi henüz doğrulanmamış gözlem gösterilir ama sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kuzey şeritli semender gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ommatotriton-ophryticus');
