INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pelobates-syriacus', 'ka', 'სად არის სირიული მყვარი დაფიქსირებული საქართველოში', 'სირიული მყვრის რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. iNaturalist ამ სახეობის საჯარო კოორდინატების უმეტესობას დაახლოებით 20 კმ-იან უჯრაში ფარავს, ამიტომ ბევრი წერტილი მიახლოებითია. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'სირიული მყვრის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pelobates-syriacus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pelobates-syriacus', 'en', 'Eastern Spadefoot: where it is recorded in Georgia', 'The Eastern Spadefoot map uses public iNaturalist photo observations in Georgia. iNaturalist obscures most public coordinates for this species within a cell of about 20 km, so many points are approximate. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. Record counts reflect observation effort, not population density.', 'Eastern Spadefoot observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pelobates-syriacus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pelobates-syriacus', 'ru', 'Где восточная чесночница отмечена в Грузии', 'Карта восточной чесночницы основана на публичных фотонаблюдениях iNaturalist в Грузии. iNaturalist скрывает большинство публичных координат этого вида в ячейке около 20 км, поэтому многие точки приблизительны. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения восточной чесночницы и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pelobates-syriacus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pelobates-syriacus', 'tr', 'Doğu kazayak kurbağası Gürcistan''da nerede kaydedildi?', 'Doğu kazayak kurbağası haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. iNaturalist bu türün açık koordinatlarının çoğunu yaklaşık 20 km''lik bir hücre içinde gizler, bu yüzden birçok nokta yaklaşıktır. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Doğu kazayak kurbağası gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pelobates-syriacus');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'pelodytes-caucasicus', 25317, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'pelodytes-caucasicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pelodytes-caucasicus', 'ka', 'სად არის კავკასიური ჯვრიანა დაფიქსირებული საქართველოში', 'კავკასიური ჯვრიანას რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. iNaturalist ამ სახეობის ყველა საჯარო კოორდინატს დაახლოებით 20 კმ-იან უჯრაში ფარავს, ამიტომ წერტილები მიახლოებითია. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'კავკასიური ჯვრიანას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pelodytes-caucasicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pelodytes-caucasicus', 'en', 'Caucasian Parsley Frog: where it is recorded in Georgia', 'The Caucasian Parsley Frog map uses public iNaturalist photo observations in Georgia. iNaturalist obscures all public coordinates for this species within a cell of about 20 km, so the points are approximate. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. Record counts reflect observation effort, not population density.', 'Caucasian Parsley Frog observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pelodytes-caucasicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pelodytes-caucasicus', 'ru', 'Где кавказская крестовка отмечена в Грузии', 'Карта кавказской крестовки основана на публичных фотонаблюдениях iNaturalist в Грузии. iNaturalist скрывает все публичные координаты этого вида в ячейке около 20 км, поэтому точки приблизительны. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения кавказской крестовки и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pelodytes-caucasicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pelodytes-caucasicus', 'tr', 'Kafkas maydanoz kurbağası Gürcistan''da nerede kaydedildi?', 'Kafkas maydanoz kurbağası haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. iNaturalist bu türün tüm açık koordinatlarını yaklaşık 20 km''lik bir hücre içinde gizler, bu yüzden noktalar yaklaşıktır. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kafkas maydanoz kurbağası gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pelodytes-caucasicus');
