INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pelophylax-ridibundus', 'ru', 'Где озёрная лягушка отмечена в Грузии', 'Карта озёрной лягушки основана на публичных фотонаблюдениях iNaturalist в Грузии. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения озёрной лягушки и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pelophylax-ridibundus');
