INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'phasianus-colchicus', 'ka', 'სად არის ხოხობი დაფიქსირებული საქართველოში', 'ხოხბის რუკა იყენებს საქართველოში iNaturalist-ის საჯარო დაკვირვებებს, რომლებიც ტყვეობაში მყოფად არ არის მონიშნული. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან; რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი. ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ნიშნავს.', 'ხოხბის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერებით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'phasianus-colchicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'phasianus-colchicus', 'en', 'Common pheasant: where it is recorded in Georgia', 'The common pheasant map uses public iNaturalist observations from Georgia that are not marked captive. Regions come from the records-by-region table; only regions with enough records are shaded on the map. Record counts reflect observation effort, not population density.', 'Common pheasant observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'phasianus-colchicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'phasianus-colchicus', 'ru', 'Где фазан отмечен в Грузии', 'Карта фазана использует публичные наблюдения из Грузии на iNaturalist, не отмеченные как содержащиеся в неволе. Регионы взяты из таблицы записей; на карте выделены только регионы с достаточным числом записей. Число записей не означает плотность популяции.', 'Наблюдения фазана и регионы с записями на карте Грузии', 'Регион с записями', 'регионы с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'phasianus-colchicus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'phasianus-colchicus', 'tr', 'Sülün Gürcistan''da nerede kaydedildi?', 'Sülün haritası Gürcistan''daki esir olarak işaretlenmemiş halka açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgesel kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler vurgulanır. Kayıt sayısı nüfus yoğunluğunu göstermez.', 'Sülün gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'phasianus-colchicus');
