INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'platyceps-najadum', 'ka', 'სად არის წენგოსფერი მცურავი დაფიქსირებული საქართველოში', 'წენგოსფერი მცურავის რუკა აერთიანებს Reptiles.ge-ის საველე ფოტოებსა და iNaturalist-ის საჯარო დაკვირვებებს. შეფერილი რეგიონები რეგიონული ცხრილის სტატუსს ეფუძნება: რუკაზე შეფერილია სულ მცირე 3 საველე ჩანაწერის მქონე რეგიონი; 1–2 ჩანაწერი ცოტად ითვლება. ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვე არ არის.', 'წენგოსფერი მცურავის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'platyceps-najadum');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'platyceps-najadum', 'en', 'Dahl''s whip snake: where it is recorded in Georgia', 'The Dahl''s whip snake map combines Reptiles.ge field photos with public iNaturalist observations. The records-by-region table determines the shaded range: regions with three or more field records are shaded on the map; one or two records count as too few records. Record counts do not measure population density.', 'Dahl''s whip snake observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'platyceps-najadum');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'platyceps-najadum', 'ru', 'Где оливковый полоз отмечен в Грузии', 'Карта оливкового полоза объединяет полевые фотографии Reptiles.ge и публичные наблюдения iNaturalist. Закрашенные регионы определяются региональной таблицей: на карте закрашены регионы с тремя и более полевыми записями; одной или двух записей мало. Число записей не отражает плотность популяции.', 'Наблюдения оливкового полоза и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'platyceps-najadum');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'platyceps-najadum', 'tr', 'Dahl kırbaç yılanı Gürcistan''da nerede kaydedildi?', 'Dahl kırbaç yılanı haritası Reptiles.ge arazi fotoğraflarını ve herkese açık iNaturalist gözlemlerini birleştirir. Boyalı bölgeler bölgesel tabloya dayanır: üç veya daha fazla arazi kaydı olan bölgeler haritada boyanır; bir veya iki kayıt az sayılır. Kayıt sayısı popülasyon yoğunluğunu göstermez.', 'Dahl kırbaç yılanı gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'platyceps-najadum');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'procyon-lotor', 41663, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'procyon-lotor');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'procyon-lotor', 'ka', 'სად არის ენოტი დაფიქსირებული საქართველოში', 'ენოტის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები შეფერილი არ არის. რეგიონული პოლიგონების გარეთ დარჩენილი წერტილები საერთო რაოდენობაში შედის, მაგრამ რეგიონს არ მიეკუთვნება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ენოტის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'procyon-lotor');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'procyon-lotor', 'en', 'Raccoon: where it is recorded in Georgia', 'The raccoon map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Points outside the regional polygons stay in the total but are not assigned to a region. Record counts reflect observation effort, not population density.', 'Raccoon observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'procyon-lotor');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'procyon-lotor', 'ru', 'Где енот-полоскун отмечен в Грузии', 'Карта енота-полоскуна использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Точки вне региональных полигонов входят в общее число, но к региону не относятся. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения енота-полоскуна и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'procyon-lotor');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'procyon-lotor', 'tr', 'Rakun Gürcistan''da nerede kaydedildi?', 'Rakun haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler boyanır; diğer bölgeler boyanmaz. Bölge poligonlarının dışında kalan noktalar toplama girer ama bir bölgeye yazılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Rakun gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'procyon-lotor');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'pseudopus-apodus', 31975, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'pseudopus-apodus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pseudopus-apodus', 'ka', 'სად არის გველხოკერა დაფიქსირებული საქართველოში', 'რუკა იყენებს საქართველოში გველხოკერას შესახებ iNaturalist-ის საჯარო დაკვირვებებს. რუკაზე შეფერილია მხოლოდ რეგიონული ცხრილის მიხედვით საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენებში ჩანაწერები ცოტაა. 2026 წლის ჩამონათვალი აღმოსავლეთ საქართველოს ასახელებს, დაკვირვებების ცხრილში კი რუკის ჩანაწერთა ზღვარს აფხაზეთიც აღწევს. ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'გველხოკერას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pseudopus-apodus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pseudopus-apodus', 'en', 'Where the European glass lizard is recorded in Georgia', 'This map uses public iNaturalist observations of the European glass lizard in Georgia. Its shaded regions are those with enough records in the records-by-region table; other regions have too few records. The 2026 checklist describes an eastern range, while Abkhazia also reaches this map''s record threshold in the observation table. Counts reflect observation effort, not population density.', 'European glass lizard observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pseudopus-apodus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pseudopus-apodus', 'ru', 'Где желтопузик отмечен в Грузии', 'Карта использует публичные наблюдения желтопузика в Грузии на iNaturalist. На карте закрашены только регионы с достаточным числом записей в таблице; в остальных записей мало. Перечень 2026 года указывает восточную Грузию, а Абхазия также достигает порога записей на этой карте. Число записей не отражает плотность популяции.', 'Наблюдения желтопузика и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pseudopus-apodus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'pseudopus-apodus', 'tr', 'Yılan kertenkele Gürcistan''da nerede kaydedildi?', 'Bu harita, Gürcistan''daki yılan kertenkeleye ait herkese açık iNaturalist gözlemlerini kullanır. Haritada yalnızca bölgesel kayıt tablosunda yeterli kaydı olan bölgeler renklendirilir; diğerlerinde kayıt azdır. 2026 listesi Doğu Gürcistan''ı belirtirken Abhazya da bu haritadaki kayıt eşiğine ulaşır. Kayıt sayısı nüfus yoğunluğunu göstermez.', 'Yılan kertenkele gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'pseudopus-apodus');
