INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'steatoda-paykulliana', 'en', 'False black widow: where it is recorded in Georgia', 'The false black widow map uses public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'False black widow distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'steatoda-paykulliana');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'steatoda-paykulliana', 'ru', 'Где ложный каракурт отмечен в Грузии', 'Карта ложного каракурта использует публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте закрашены только регионы с достаточным числом записей.', 'Данные о распространении ложного каракурта и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'steatoda-paykulliana');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'steatoda-paykulliana', 'tr', 'Yalancı karakurt Gürcistan''da nerede kaydedildi?', 'Yalancı karakurt haritası herkese açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler boyanır.', 'Yalancı karakurtun Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'steatoda-paykulliana');
