INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'telescopus-fallax', 'ka', 'სად არის კატისთვალა დაფიქსირებული საქართველოში', 'კატისთვალას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, ხელით შერჩეულ ლოკალიტეტებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'კატისთვალას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'telescopus-fallax');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'telescopus-fallax', 'en', 'European cat snake: where it is recorded in Georgia', 'The European cat snake map combines Reptiles.ge editorial photo records, hand-curated localities, and public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'European cat snake distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'telescopus-fallax');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'telescopus-fallax', 'ru', 'Где европейский кошачий уж отмечен в Грузии', 'Карта европейского кошачьего ужа объединяет редакционные фотозаписи Reptiles.ge, вручную отобранные локалитеты и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении европейского кошачьего ужа и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'telescopus-fallax');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'telescopus-fallax', 'tr', 'Avrupa kedi yılanı Gürcistan''da nerede kaydedildi?', 'Avrupa kedi yılanı haritası Reptiles.ge editoryal fotoğraf kayıtlarını, elle seçilmiş lokaliteleri ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'Avrupa kedi yılanının Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'telescopus-fallax');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'testudo-graeca', 40023, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'testudo-graeca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'testudo-graeca', 'ka', 'სად არის ხმელთაშუაზღვეთის კუ დაფიქსირებული საქართველოში', 'ხმელთაშუაზღვეთის კუს რუკა აჩვენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რუკაზე მხოლოდ ის რეგიონებია გამოკვეთილი, რომლებსაც ჩანაწერების ცხრილში საკმარისი ჩანაწერი აქვს. iNaturalist ამ სახეობის საჯარო კოორდინატებს ფარავს, ამიტომ წერტილები მიახლოებითია: ზოგი საზღვარს გადაღმა ან მეზობელ რეგიონში ხვდება, ხოლო რეგიონების საზღვრებს გარეთ მოხვედრილი წერტილები ცხრილში არ ითვლება. დასავლეთ საქართველოს რეგიონები, სადაც მხოლოდ ცალკეული ჩანაწერია, გამოკვეთილი არ არის. გამოკვეთილი რეგიონი არ ნიშნავს მის მთელ ტერიტორიაზე გავრცელებას; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ხმელთაშუაზღვეთის კუს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'testudo-graeca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'testudo-graeca', 'en', 'Where Mediterranean tortoises are recorded in Georgia', 'The Mediterranean tortoise map shows public iNaturalist observations in Georgia. Only regions with enough records in the records table are shaded on the map. iNaturalist obscures the public coordinates of this species, so points are approximate, some fall across a border or a regional boundary, and those outside the region outlines are not counted. Regions in the west with single records are not shaded. A shaded region does not mean the tortoise occupies all of it; record counts reflect observation effort, not population density.', 'Mediterranean tortoise field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'testudo-graeca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'testudo-graeca', 'ru', 'Где средиземноморская черепаха отмечена в Грузии', 'Карта средиземноморской черепахи показывает публичные наблюдения iNaturalist в Грузии. На карте выделены только регионы с достаточным числом записей в таблице записей. iNaturalist скрывает публичные координаты этого вида, поэтому точки приблизительны: некоторые попадают за границу или в соседний регион, а точки за границами регионов в таблице не учитываются. Регионы запада Грузии с единичными записями не выделены. Выделенный регион не означает присутствие на всей его территории; число записей не измеряет плотность популяции.', 'Полевые записи средиземноморской черепахи и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'testudo-graeca');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'testudo-graeca', 'tr', 'Akdeniz tosbağası Gürcistan''da nerede kaydedildi?', 'Akdeniz tosbağası haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini gösterir. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır. iNaturalist bu türün açık koordinatlarını gizler; bu yüzden noktalar yaklaşıktır, bazıları sınırın ötesine veya komşu bölgeye düşer ve bölge sınırları dışında kalan noktalar tabloda sayılmaz. Batı Gürcistan''da yalnızca tekil kaydı olan bölgeler vurgulanmaz. Vurgulanan bölge, türün o bölgenin her yerinde bulunduğu anlamına gelmez; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Akdeniz tosbağasının arazi kayıtları ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'testudo-graeca');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'trachemys-scripta', 39782, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'trachemys-scripta');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'trachemys-scripta', 'ka', 'სად არის წითელყურა კუ დაფიქსირებული საქართველოში', 'წითელყურა კუს რუკა აჩვენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რუკაზე მხოლოდ ის რეგიონებია გამოკვეთილი, რომლებსაც ჩანაწერების ცხრილში საკმარისი ჩანაწერი აქვს: თბილისი, აჭარა და აფხაზეთი. იმერეთი, ქვემო ქართლი და გურია, სადაც მხოლოდ ცალკეული ჩანაწერია, გამოკვეთილი არ არის. წითელყურა კუ შემოტანილი სახეობაა, ამიტომ ჩანაწერი შეიძლება გაშვებულ ან გაქცეულ შინაურ კუს ეკუთვნოდეს და თავისთავად გამრავლებად პოპულაციას არ ადასტურებს. გამოკვეთილი რეგიონი არ ნიშნავს მის მთელ ტერიტორიაზე გავრცელებას; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'წითელყურა კუს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'trachemys-scripta');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'trachemys-scripta', 'en', 'Where pond sliders are recorded in Georgia', 'The pond slider map shows public iNaturalist observations in Georgia. Only regions with enough records in the records table are shaded on the map: Tbilisi, Adjara, and Abkhazia. Imereti, Kvemo Kartli, and Guria have single records and are not shaded. The pond slider is an introduced species, so a record can be a released or escaped pet and does not by itself show a reproducing population. A shaded region does not mean the turtle lives everywhere in it; record counts reflect observation effort, not population density.', 'Pond slider field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'trachemys-scripta');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'trachemys-scripta', 'ru', 'Где красноухая черепаха отмечена в Грузии', 'Карта красноухой черепахи показывает публичные наблюдения iNaturalist в Грузии. На карте выделены только регионы с достаточным числом записей в таблице записей: Тбилиси, Аджария и Абхазия. Имеретия, Квемо Картли и Гурия, где есть лишь единичные записи, не выделены. Красноухая черепаха — интродуцированный вид, поэтому запись может относиться к выпущенной или сбежавшей домашней черепахе и сама по себе не подтверждает размножающуюся популяцию. Выделенный регион не означает присутствие на всей его территории; число записей не измеряет плотность популяции.', 'Полевые записи красноухой черепахи и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'trachemys-scripta');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'trachemys-scripta', 'tr', 'Kırmızı yanaklı su kaplumbağası Gürcistan''da nerede kaydedildi?', 'Kırmızı yanaklı su kaplumbağası haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini gösterir. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır: Tiflis, Acara ve Abhazya. Yalnızca tekil kaydı olan İmereti, Kvemo Kartli ve Gurya vurgulanmaz. Kırmızı yanaklı su kaplumbağası sokulmuş bir türdür; bu yüzden bir kayıt doğaya bırakılmış veya kaçmış bir evcil hayvana ait olabilir ve tek başına üreyen bir popülasyonu göstermez. Vurgulanan bölge, türün o bölgenin her yerinde bulunduğu anlamına gelmez; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Kırmızı yanaklı su kaplumbağasının arazi kayıtları ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'trachemys-scripta');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'turdus-merula', 12716, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'turdus-merula');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'turdus-merula', 'ka', 'სად არის შავი შაშვი დაფიქსირებული საქართველოში', 'შავი შაშვის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები შეფერილი არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'შავი შაშვის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'turdus-merula');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'turdus-merula', 'en', 'Common blackbird: where it is recorded in Georgia', 'The common blackbird map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Common blackbird observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'turdus-merula');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'turdus-merula', 'ru', 'Где чёрный дрозд отмечен в Грузии', 'Карта чёрного дрозда использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения чёрного дрозда и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'turdus-merula');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'turdus-merula', 'tr', 'Karatavuk Gürcistan''da nerede kaydedildi?', 'Karatavuk haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler boyanır; diğer bölgeler boyanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Karatavuk gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'turdus-merula');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'tyto-alba', 20445, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'tyto-alba');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'tyto-alba', 'ka', 'სად არის ბუხრინწა დაფიქსირებული საქართველოში', 'ბუხრინწას რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები შეფერილი არ არის. ცალკეული დაკვირვების ადგილის წარწერა კოორდინატს რომ არ ემთხვევა, ეს წარწერა იმ რეგიონის ჩანაწერად არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ბუხრინწას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'tyto-alba');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'tyto-alba', 'en', 'Western barn owl: where it is recorded in Georgia', 'The western barn owl map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Some place names on individual observations do not match the coordinate, and a mismatched label does not count as a record for that named region. Record counts reflect observation effort, not population density.', 'Western barn owl observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'tyto-alba');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'tyto-alba', 'ru', 'Где сипуха отмечена в Грузии', 'Карта сипухи использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Если подпись места у отдельного наблюдения не совпадает с координатой, эта подпись не считается записью для названного региона. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения сипухи и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'tyto-alba');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'tyto-alba', 'tr', 'Peçeli baykuş Gürcistan''da nerede kaydedildi?', 'Peçeli baykuş haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler boyanır; diğer bölgeler boyanmaz. Tek bir gözlemin yer adı koordinatla uyuşmuyorsa bu ad o bölge için kayıt sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Peçeli baykuş gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'tyto-alba');
