INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ursus-arctos', 'ka', 'სად არის მურა დათვი დაფიქსირებული საქართველოში', 'მურა დათვის რუკა იყენებს iNaturalist-ის საჯარო ფოტოდაკვირვებებს საქართველოდან. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები, ხოლო მცირე რაოდენობის ან გაურკვეველი ჩანაწერების რეგიონები შეფერილი არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'მურა დათვის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ursus-arctos');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ursus-arctos', 'en', 'Brown bear: where it is recorded in Georgia', 'The brown bear map uses public iNaturalist photo observations from Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map, while low-count or uncertain regions are not shaded. Record counts reflect observation effort, not population density.', 'Brown bear observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ursus-arctos');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ursus-arctos', 'ru', 'Где бурый медведь отмечен в Грузии', 'Карта бурого медведя использует публичные фотонаблюдения iNaturalist из Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей, а регионы с малым числом или неопределёнными записями не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения бурого медведя и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ursus-arctos');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'ursus-arctos', 'tr', 'Boz ayı Gürcistan''da nerede kaydedildi?', 'Boz ayı haritası Gürcistan''daki herkese açık iNaturalist fotoğraf gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler boyanır; az sayıdaki veya belirsiz kayıtların bulunduğu bölgeler boyanmaz. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu ölçmez.', 'Boz ayı gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'ursus-arctos');
