INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-darevskii', 'ru', 'Где гадюка Даревского отмечена в Грузии', 'Карта гадюки Даревского использует публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте закрашены только регионы с достаточным числом записей, а регионы, где записей мало, не закрашены.', 'Наблюдения гадюки Даревского и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-darevskii');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-darevskii', 'tr', 'Darevsky engereği Gürcistan''da nerede kaydedildi?', 'Darevsky engereği haritası herkese açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler boyanır, kaydı az olan bölgeler boyanmaz.', 'Darevsky engereğinin gözlemleri ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-darevskii');
