INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-kaznakovi', 'ka', 'სად არის კავკასიური გველგესლა დაფიქსირებული საქართველოში', 'კავკასიური გველგესლის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, ხელით შერჩეულ ლოკალიტეტებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'კავკასიური გველგესლის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-kaznakovi');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-kaznakovi', 'en', 'Caucasus viper: where it is recorded in Georgia', 'The Caucasus viper map combines Reptiles.ge editorial photo records, hand-curated localities, and public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'Caucasus viper distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-kaznakovi');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-kaznakovi', 'ru', 'Где кавказская гадюка отмечена в Грузии', 'Карта кавказской гадюки объединяет редакционные фотозаписи Reptiles.ge, вручную отобранные локалитеты и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении кавказской гадюки и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-kaznakovi');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-kaznakovi', 'tr', 'Kafkas engereği Gürcistan''da nerede kaydedildi?', 'Kafkas engereği haritası Reptiles.ge editoryal fotoğraf kayıtlarını, elle seçilmiş lokaliteleri ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'Kafkas engereğinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-kaznakovi');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'vipera-renardi', 114991, 'record-summary', 1 WHERE EXISTS (SELECT 1 FROM species WHERE id = 'vipera-renardi');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-renardi', 'ka', 'სად არის ველის გველგესლა დაფიქსირებული საქართველოში', 'ველის გველგესლას რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს Vipera renardi-ზე. რეგიონი, სადაც სულ მცირე ერთი საველე ჩანაწერია, რუკაზე შეფერილია; ჩანაწერის არმქონე რეგიონი შეფერილი არ არის. საჯარო კოორდინატების ნაწილი დაფარულია, ამიტომ რეგიონების საზღვართან წერტილები მიახლოებითია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ველის გველგესლას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-renardi');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-renardi', 'en', 'Steppe viper: where it is recorded in Georgia', 'The steppe viper map uses public iNaturalist observations of Vipera renardi. A region with at least one field record is shaded on the map; a region with no records is not shaded. Some public coordinates are obscured, so points near regional borders are approximate. Record counts reflect observation effort, not population density.', 'Steppe viper observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-renardi');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-renardi', 'ru', 'Где степная гадюка отмечена в Грузии', 'Карта степной гадюки использует публичные наблюдения iNaturalist для Vipera renardi. Регион хотя бы с одной полевой записью закрашен на карте; регион без записей не закрашен. Часть публичных координат скрыта, поэтому точки у границ регионов приблизительны. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения степной гадюки и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-renardi');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-renardi', 'tr', 'Bozkır engereği Gürcistan''da nerede kaydedildi?', 'Bozkır engereği haritası Vipera renardi için herkese açık iNaturalist gözlemlerini kullanır. En az bir arazi kaydı olan bölge haritada boyanır; kaydı olmayan bölge boyanmaz. Bazı halka açık koordinatlar gizlendiğinden bölge sınırlarına yakın noktalar yaklaşıktır. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu ölçmez.', 'Bozkır engereğinin gözlemleri ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-renardi');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'vipera-transcaucasiana', 1701183, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'vipera-transcaucasiana');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-transcaucasiana', 'ka', 'სად არის ცხვირრქოსანი გველგესლა დაფიქსირებული საქართველოში', 'ცხვირრქოსანი გველგესლას რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს, რომლებიც Vipera meridionalis transcaucasiana-ს სახელითაა შეტანილი. რუკაზე შეფერილია მხოლოდ ცხრილის მიხედვით საკმარისი ჩანაწერების მქონე რეგიონები. საჯარო კოორდინატები დაფარულია, ამიტომ რეგიონების საზღვართან წერტილები მიახლოებითია; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ცხვირრქოსანი გველგესლას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-transcaucasiana');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-transcaucasiana', 'en', 'Where the nose-horned viper is recorded in Georgia', 'The nose-horned viper map uses public iNaturalist observations filed as Vipera meridionalis transcaucasiana. Only regions with enough records in the records table are shaded on the map. Public coordinates are obscured, so points near regional borders are approximate; record counts do not measure population density.', 'Nose-horned viper observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-transcaucasiana');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-transcaucasiana', 'ru', 'Где носатая гадюка отмечена в Грузии', 'Карта носатой гадюки использует публичные наблюдения iNaturalist под названием Vipera meridionalis transcaucasiana. На карте закрашены только регионы с достаточным числом записей в таблице. Публичные координаты скрыты, поэтому точки у границ регионов приблизительны; число записей не измеряет плотность популяции.', 'Наблюдения носатой гадюки и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-transcaucasiana');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vipera-transcaucasiana', 'tr', 'Boynuzlu engerek Gürcistan''da nerede kaydedildi?', 'Boynuzlu engerek haritası, iNaturalist''te Vipera meridionalis transcaucasiana adıyla kayıtlı halka açık gözlemleri kullanır. Haritada yalnızca tabloda yeterli kaydı olan bölgeler boyanır. Halka açık koordinatlar gizlendiğinden bölge sınırlarına yakın noktalar yaklaşıktır; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Boynuzlu engerek gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vipera-transcaucasiana');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'vulpes-vulpes', 42069, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'vulpes-vulpes');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vulpes-vulpes', 'ka', 'სად არის მელა დაფიქსირებული საქართველოში', 'მელას რუკა იყენებს საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რუკაზე შეფერილია მხოლოდ რეგიონი, რომელსაც ქვემოთ მოცემულ ცხრილში საკმარისი ჩანაწერები აქვს; სხვა წერტილები ცალკეული ჩანაწერებია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მელას საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vulpes-vulpes');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vulpes-vulpes', 'en', 'Red fox: where it is recorded in Georgia', 'The red fox map uses public iNaturalist photo observations from Georgia. Only regions with enough records in the records-by-region table are shaded on the map; other points are individual records. Record counts reflect observation effort, not population density.', 'Red fox field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vulpes-vulpes');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vulpes-vulpes', 'ru', 'Где лисица отмечена в Грузии', 'Карта лисицы использует публичные фотонаблюдения iNaturalist из Грузии. На карте окрашены только регионы с достаточным числом записей в таблице; остальные точки — отдельные находки. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Полевые записи лисицы и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vulpes-vulpes');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'vulpes-vulpes', 'tr', 'Kızıl tilki Gürcistan''da nerede kaydedildi?', 'Kızıl tilki haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler boyanır; diğer noktalar tekil kayıtlardır. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu değil.', 'Kızıl tilkinin Gürcistan''daki arazi kayıtları ve kayıt bulunan bölgeleri', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'vulpes-vulpes');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'xerotyphlops-vermicularis', 514727, 'record-summary', NULL WHERE EXISTS (SELECT 1 FROM species WHERE id = 'xerotyphlops-vermicularis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'xerotyphlops-vermicularis', 'ka', 'სად არის გველბრუცა დაფიქსირებული საქართველოში', 'გველბრუცას რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. გამოკვეთილია მხოლოდ ის რეგიონები, რომლებსაც ჩანაწერების რეგიონულ ცხრილში საკმარისი ჩანაწერები აქვთ; ცალკეული ჩანაწერი მთელი რეგიონის გავრცელებას არ ნიშნავს. ზოგი საჯარო კოორდინატი დაფარულია და რეგიონის ჩანაწერებში არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'გველბრუცას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'xerotyphlops-vermicularis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'xerotyphlops-vermicularis', 'en', 'European blind snake: where it is recorded in Georgia', 'The European blind snake map uses public iNaturalist observations in Georgia. Only regions with enough records in the records-by-region table are highlighted; isolated records do not establish region-wide distribution. Some public coordinates are obscured and do not count toward a region''s records. Record counts reflect observation effort, not population density.', 'European blind snake observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'xerotyphlops-vermicularis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'xerotyphlops-vermicularis', 'ru', 'Где червеобразная слепозмейка отмечена в Грузии', 'Карта червеобразной слепозмейки основана на публичных наблюдениях iNaturalist в Грузии. Выделены только регионы с достаточным числом записей в таблице; отдельная запись не означает распространение по всему региону. Некоторые публичные координаты скрыты и не учитываются в записях региона. Число записей отражает активность наблюдателей, не плотность популяции.', 'Наблюдения червеобразной слепозмейки и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'xerotyphlops-vermicularis');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'xerotyphlops-vermicularis', 'tr', 'Kör yılan Gürcistan''da nerede kaydedildi?', 'Kör yılan haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Yalnızca bölgesel kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır; tek bir kayıt tüm bölgede yayılış anlamına gelmez. Bazı halka açık koordinatlar gizlenmiştir ve bölgenin kayıtlarına sayılmaz. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Kör yılan gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'xerotyphlops-vermicularis');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'zamenis-hohenackeri', 74007, 'record-summary', 1 WHERE EXISTS (SELECT 1 FROM species WHERE id = 'zamenis-hohenackeri');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'zamenis-hohenackeri', 'ka', 'სად არის ამიერკავკასიური მცურავი დაფიქსირებული საქართველოში', 'ამიერკავკასიური მცურავის რუკა აერთიანებს Reptiles.ge-ის საველე ფოტოებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონი, სადაც სულ მცირე ერთი საველე ჩანაწერია, რუკაზე შეფერილია. iNaturalist-ის ზოგი კოორდინატი დაფარულია, ამიტომ რეგიონების საზღვრებთან მდებარე წერტილები მიახლოებითია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ამიერკავკასიური მცურავის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'zamenis-hohenackeri');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'zamenis-hohenackeri', 'en', 'Transcaucasian rat snake: where it is recorded in Georgia', 'The Transcaucasian rat snake map combines Reptiles.ge field photos with public iNaturalist observations. A region with at least one field record is shaded on the map. Some iNaturalist coordinates are obscured, so points near regional borders are approximate. Record counts reflect observation effort, not population density.', 'Transcaucasian rat snake observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'zamenis-hohenackeri');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'zamenis-hohenackeri', 'ru', 'Где закавказский полоз отмечен в Грузии', 'Карта закавказского полоза объединяет полевые фотографии Reptiles.ge и публичные наблюдения iNaturalist. Регион хотя бы с одной полевой записью закрашен на карте. Координаты некоторых наблюдений iNaturalist скрыты, поэтому точки у границ регионов приблизительны. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения закавказского полоза и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'zamenis-hohenackeri');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'zamenis-hohenackeri', 'tr', 'Transkafkas sıçan yılanı Gürcistan''da nerede kaydedildi?', 'Transkafkas sıçan yılanı haritası Reptiles.ge arazi fotoğraflarını ve herkese açık iNaturalist gözlemlerini birleştirir. En az bir saha kaydı olan bölge haritada boyanır. Bazı iNaturalist koordinatları gizlendiğinden bölge sınırlarındaki noktalar yaklaşıktır. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu ölçmez.', 'Transkafkas sıçan yılanının gözlemleri ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'zamenis-hohenackeri');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) SELECT 'zamenis-longissimus', 74009, 'record-summary', 1 WHERE EXISTS (SELECT 1 FROM species WHERE id = 'zamenis-longissimus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'zamenis-longissimus', 'ka', 'სად არის ესკულაპის მცურავი დაფიქსირებული საქართველოში', 'ესკულაპის მცურავის რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს Zamenis longissimus-ზე. რეგიონი, სადაც სულ მცირე ერთი საველე ჩანაწერია, რუკაზე შეფერილია; ჩანაწერის არმქონე რეგიონი შეფერილი არ არის. საჯარო კოორდინატების ნაწილი დაფარულია, ამიტომ რეგიონების საზღვართან წერტილები მიახლოებითია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ესკულაპის მცურავის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'zamenis-longissimus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'zamenis-longissimus', 'en', 'Aesculapian snake: where it is recorded in Georgia', 'The Aesculapian snake map uses public iNaturalist observations of Zamenis longissimus. A region with at least one field record is shaded on the map; a region with no records is not shaded. Some public coordinates are obscured, so points near regional borders are approximate. Record counts reflect observation effort, not population density.', 'Aesculapian snake observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'zamenis-longissimus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'zamenis-longissimus', 'ru', 'Где эскулапов полоз отмечен в Грузии', 'Карта эскулапова полоза использует публичные наблюдения iNaturalist для Zamenis longissimus. Регион хотя бы с одной полевой записью закрашен на карте; регион без записей не закрашен. Часть публичных координат скрыта, поэтому точки у границ регионов приблизительны. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения эскулапова полоза и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'zamenis-longissimus');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) SELECT 'zamenis-longissimus', 'tr', 'Eskülap yılanı Gürcistan''da nerede kaydedildi?', 'Eskülap yılanı haritası Zamenis longissimus için herkese açık iNaturalist gözlemlerini kullanır. En az bir arazi kaydı olan bölge haritada boyanır; kaydı olmayan bölge boyanmaz. Bazı halka açık koordinatlar gizlendiğinden bölge sınırlarına yakın noktalar yaklaşıktır. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu ölçmez.', 'Eskülap yılanının gözlemleri ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL WHERE EXISTS (SELECT 1 FROM species_range_maps WHERE species_id = 'zamenis-longissimus');
